/* Original bilingual extensions. Load after lessons.js as a classic script.
   These focused models support further study; implementation details vary.
   Labs are local calculations or read-only inspection, with no configuration writes. */
const ADVANCED = [
  {
    id:31,module:8,model:'routing',
    title:{en:'Binary subnet exercises and aligned allocation',ta:'Binary subnet கணக்குகளும் சரியான எல்லைகளில் ஒதுக்கீடும்'},
    summary:{en:'Derive subnet boundaries from bits, allocate unequal blocks, and test whether aggregation would accidentally advertise space you do not control.',ta:'Bits அடிப்படையில் subnet எல்லைகளைக் கணக்கிட்டு, வெவ்வேறு அளவுள்ள blocks ஒதுக்கி, aggregation மூலம் நமக்குச் சொந்தமில்லாத address பகுதி அறிவிக்கப்படுமா என்று ஆராய்வோம்.'},
    prerequisites:{en:'IPv4 notation, CIDR prefixes, longest-prefix routing, and powers of two.',ta:'IPv4 எழுதுமுறை, CIDR prefix, longest-prefix routing, இரண்டின் அடுக்குகள் ஆகியவை தெரிந்திருக்க வேண்டும்.'},
    objectives:{en:['Compute network and broadcast addresses with binary AND.','Allocate VLSM blocks without overlap or misalignment.','Separate address counts, usable hosts, and route aggregation.'],ta:['Binary AND மூலம் network, broadcast address கணக்கிடுதல்.','ஒன்றோடொன்று மோதாத, சரியான எல்லைகளுள்ள VLSM blocks ஒதுக்குதல்.','மொத்த address எண்ணிக்கை, பயன்படும் host எண்ணிக்கை, route aggregation ஆகியவற்றை வேறுபடுத்துதல்.']},
    sections:[
      {heading:{en:'A prefix is a bit boundary',ta:'Prefix என்பது bit எல்லை'},body:{en:'An IPv4 prefix fixes its leftmost bits. For /27, the mask is 255.255.255.224; its final octet is 11100000. Write 77 as 01001101 and apply AND to obtain 01000000, or 64. The remaining five bits range from zero through 31, so the block ends at 95. Decimal shortcuts work only when they preserve this alignment. An address ending in .77 is a host position, not a valid /27 network boundary.',ta:'IPv4 prefix இடப்புற bits-ஐ நிர்ணயிக்கிறது. /27 mask 255.255.255.224; கடைசி octet 11100000. 77 என்பதை 01001101 என்று எழுதி AND செய்தால் 01000000, அதாவது 64 கிடைக்கும். மீதமுள்ள ஐந்து bits பூஜ்யத்திலிருந்து 31 வரை மாறுவதால் block 95-ல் முடிகிறது. Decimal குறுக்குவழியும் இந்த alignment-ஐக் காக்க வேண்டும். .77 என்பது host இடம்; /27 network தொடக்க எல்லை அல்ல.'}},
      {heading:{en:'An address plan is not a forwarding policy',ta:'Address திட்டமும் forwarding policy-யும் ஒன்றல்ல'},body:{en:'A host uses its configured prefix to decide whether a destination is directly reachable on the link, while a router can install more-specific routes inside a larger aggregate. Counting addresses does not establish reachability or access permission. Record gateways and intended routing boundaries alongside the allocation so a mathematically correct block does not become an operationally ambiguous network.',ta:'Destination நேரடியாக link-ல் உள்ளதா என்பதை host தன் configured prefix மூலம் தீர்மானிக்கும்; router பெரிய aggregate-க்குள் மேலும் specific routes நிறுவலாம். Address எண்ணிக்கை மட்டும் reachability அல்லது அணுகல் அனுமதியை உறுதிப்படுத்தாது. ஒதுக்கீட்டுடன் gateways, திட்டமிட்ட routing எல்லைகளையும் பதிவு செய்ய வேண்டும்; கணிதப்படி சரியான block நடைமுறையில் குழப்பமான network ஆகாமல் இது உதவும்.'}},
      {heading:{en:'Allocate the largest requirement first',ta:'பெரிய தேவைக்கு முதலில் இடம் ஒதுக்குதல்'},body:{en:'For ordinary multi-access IPv4 subnets, reserve the network and directed-broadcast positions when choosing capacity. A requirement for 50 hosts needs /26, not /27. Allocate larger blocks before smaller ones to reduce fragmentation, then verify every interval. A /31 on a point-to-point link is a standardized exception with two endpoint addresses; a /32 is one address. These exceptions mean subtracting two from every block is an incorrect universal rule.',ta:'வழக்கமான multi-access IPv4 subnet-ல் capacity தேர்வுசெய்யும்போது network, directed-broadcast இடங்களை ஒதுக்கிவைக்க வேண்டும். 50 hosts-க்கு /26 தேவை; /27 போதாது. பெரிய blocks-ஐ முதலில் ஒதுக்கினால் சிதறிய காலியிடங்கள் குறையும்; பிறகு ஒவ்வொரு இடைவெளியையும் சரிபார்க்க வேண்டும். Point-to-point link-ன் /31-ல் இரண்டு endpoint addresses பயன்படும்; /32 ஒரே address. எனவே எல்லா block எண்ணிக்கையிலிருந்தும் இரண்டைக் கழிப்பது பொதுவிதி அல்ல.'}},
      {heading:{en:'Aggregation needs both alignment and ownership',ta:'Aggregation-க்கு alignment மட்டுமல்ல உரிமையும் தேவை'},body:{en:'Two adjacent /27 blocks beginning at .64 and .96 combine into .64/26 because they share the first 26 bits. Blocks beginning at .32 and .64 are adjacent but cannot form a single /26: their common aligned covering prefix includes additional space. A summary route makes a reachability claim about its whole interval. Check downstream specific routes and discard behavior for unused space so an aggregate does not create loops or leak somebody else’s destinations.',ta:'.64, .96-ல் தொடங்கும் அடுத்தடுத்த /27 blocks முதல் 26 bits-ஐப் பகிர்வதால் .64/26 ஆக இணைக்கலாம். .32, .64 blocks அடுத்தடுத்து இருந்தாலும் ஒரே /26 ஆகாது; அவற்றை உள்ளடக்கும் பொதுவான aligned prefix கூடுதல் இடத்தையும் சேர்க்கும். Summary route முழு இடைவெளிக்கும் reachability இருப்பதாகக் கூறுகிறது. காலியிடங்களுக்கான discard நடைமுறையையும் கீழ்நிலை specific routes-ஐயும் பார்த்தால்தான் loop அல்லது பிறருடைய destination அறிவிப்பு தவிர்க்கப்படும்.'}}
    ],
    example:{en:'Split 192.0.2.0/24 for 100, 50, and 20 hosts. Assign 192.0.2.0/25, 192.0.2.128/26, and 192.0.2.192/27. Their conventional capacities are 126, 62, and 30 hosts. The unused block is 192.0.2.224/27. For 192.0.2.77/27, the network is .64, broadcast .95, and conventional host range .65–.94. Documentation addresses here describe arithmetic, not a proposed public allocation.',ta:'192.0.2.0/24-ஐ 100, 50, 20 hosts-க்குப் பிரிப்போம். 192.0.2.0/25, 192.0.2.128/26, 192.0.2.192/27 என்று ஒதுக்கினால் முறையே 126, 62, 30 hosts பயன்படும். 192.0.2.224/27 மீதமிருக்கும். 192.0.2.77/27-க்கு network .64, broadcast .95, வழக்கமான host வரம்பு .65–.94. இவை கணக்கைப் புரியவைக்கும் documentation addresses; உண்மையான public ஒதுக்கீடு அல்ல.'},
    failure:{en:'An administrator assigns 192.0.2.96/26 expecting a new block. Clearing host bits reveals 192.0.2.64/26, which overlaps an existing allocation. Diagnose with integer intervals and mask operations before investigating ARP: inconsistent masks can make hosts disagree about which destinations are on-link.',ta:'192.0.2.96/26 புதிய block என்று நிர்வாகி நினைக்கிறார். Host bits நீக்கினால் 192.0.2.64/26 கிடைத்து ஏற்கெனவே உள்ள ஒதுக்கீட்டுடன் மோதுகிறது. ARP-ஐ ஆராயும்முன் mask கணக்கையும் address இடைவெளியையும் சரிபார்க்க வேண்டும். வேறுபட்ட masks காரணமாக எந்த destination on-link என்பதில் hosts முரண்படலாம்.'},
    lab:{commands:"python3 - <<'PY'\nimport ipaddress\nn = ipaddress.ip_network('192.0.2.77/27', strict=False)\nprint(n, n.netmask, n.broadcast_address, n.num_addresses)\nprint(format(77, '08b'), format(224, '08b'), format(77 & 224, '08b'))\nfor p in ('192.0.2.0/25','192.0.2.128/26','192.0.2.192/27'):\n    x = ipaddress.ip_network(p)\n    print(x, x.num_addresses - 2)\nPY",guidance:{en:'Use Python 3 with its standard library. Predict every output before running this entirely local calculation; no interface addresses are assigned.',ta:'Python 3 standard library மட்டும் போதும். முழுவதும் உள்ளூரில் நடக்கும் இந்தக் கணக்கை இயக்கும்முன் ஒவ்வொரு வெளியீட்டையும் கணிக்கவும்; interface address மாற்றப்படாது.'},expected:{en:'The first line identifies 192.0.2.64/27, mask .224, broadcast .95, and 32 addresses. Capacities are 126, 62, and 30.',ta:'முதல் வரியில் 192.0.2.64/27, mask .224, broadcast .95, 32 addresses வரும். Host capacity 126, 62, 30 என்று வரும்.'},cleanup:{en:'No cleanup is needed; the process exits without writing files or changing routes.',ta:'Files எழுதவோ routes மாற்றவோ செய்யாமல் process முடிவதால் cleanup தேவையில்லை.'}},
    questions:[
      {question:{en:'Which network contains 192.0.2.77/27?',ta:'192.0.2.77/27 எந்த network-ல் உள்ளது?'},options:{en:['192.0.2.64/27','192.0.2.77/27','192.0.2.96/27'],ta:['192.0.2.64/27','192.0.2.77/27','192.0.2.96/27']},answer:0,explanation:{en:'AND with 224 clears five host bits, leaving 64; the block spans 64 through 95.',ta:'224 உடன் AND செய்தால் ஐந்து host bits நீங்கி 64 கிடைக்கும்; block 64 முதல் 95 வரை.'}},
      {question:{en:'Which adjacent pair can form one /26?',ta:'எந்த அடுத்தடுத்த blocks ஒரே /26 ஆகும்?'},options:{en:['.64/27 and .96/27','.32/27 and .64/27','.96/27 and .128/27'],ta:['.64/27 மற்றும் .96/27','.32/27 மற்றும் .64/27','.96/27 மற்றும் .128/27']},answer:0,explanation:{en:'A /26 begins on a multiple of 64; both component blocks must fall inside that boundary.',ta:'/26 என்பது 64-ன் மடங்கில் தொடங்கும்; இரண்டு blocks-மும் அதன் எல்லைக்குள் இருக்க வேண்டும்.'}},
      {question:{en:'How many endpoint addresses can an RFC 3021 /31 provide?',ta:'RFC 3021 /31 எத்தனை endpoint addresses தரும்?'},options:{en:['Two on a point-to-point link','Zero in every situation','Thirty usable addresses'],ta:['Point-to-point link-ல் இரண்டு','எல்லாச் சூழலிலும் பூஜ்யம்','முப்பது பயன்படும் addresses']},answer:0,explanation:{en:'The point-to-point exception uses both positions as endpoints instead of network and broadcast reservations.',ta:'Point-to-point விதிவிலக்கில் network, broadcast ஒதுக்கீட்டுக்குப் பதிலாக இரு இடங்களும் endpoints ஆகும்.'}}
    ],refs:[['CIDR address strategy','https://www.rfc-editor.org/rfc/rfc4632.html'],['IPv4 /31 links','https://www.rfc-editor.org/rfc/rfc3021.html']]
  },
  {
    id:32,module:8,model:'switch',
    title:{en:'Ethernet frames, Wi-Fi headers, and radio airtime',ta:'Ethernet frames, Wi-Fi headers மற்றும் radio நேரப் பயன்பாடு'},
    summary:{en:'Trace what a capture can actually show, distinguish frame overhead from radio overhead, and reason about retries using airtime rather than advertised PHY speed.',ta:'Capture உண்மையில் எதைக் காட்டுகிறது என்று அறிந்து, frame overhead-ஐ radio overhead-லிருந்து பிரித்து, விளம்பர PHY வேகத்துக்குப் பதிலாக airtime மூலம் retries-ன் விளைவைப் புரிந்துகொள்வோம்.'},
    prerequisites:{en:'MAC learning, encapsulation, MTU, and basic Wi-Fi association.',ta:'MAC learning, encapsulation, MTU, அடிப்படை Wi-Fi association தெரிந்திருக்க வேண்டும்.'},
    objectives:{en:['Account for Ethernet payload and wire occupancy.','Explain multiple Wi-Fi address fields and local acknowledgements.','Diagnose contention separately from weak radio signal.'],ta:['Ethernet payload மற்றும் கம்பியில் பயன்படுத்தும் நேரத்தைக் கணக்கிடுதல்.','Wi-Fi address fields, உள்ளூர் acknowledgements விளக்குதல்.','Weak signal பிரச்சினையிலிருந்து contention-ஐத் தனியே கண்டறிதல்.']},
    sections:[
      {heading:{en:'The captured frame is not the whole wire event',ta:'Capture frame முழு wire நிகழ்வு அல்ல'},body:{en:'An untagged Ethernet frame normally has a 14-byte header and a four-byte FCS, with a minimum frame length of 64 bytes from destination MAC through FCS. A 1500-byte payload therefore produces 1518 bytes at this level. Preamble, start delimiter, and the inter-frame gap consume additional transmission time. Captures often omit FCS and physical framing. VLAN tags add bytes, while segmentation and checksum offloads can make host captures differ from packets actually placed on the wire.',ta:'Untagged Ethernet frame-ல் பொதுவாக 14-byte header, நான்கு-byte FCS இருக்கும்; destination MAC முதல் FCS வரை குறைந்தது 64 bytes தேவை. 1500-byte payload இந்த நிலையில் 1518 bytes ஆகிறது. Preamble, start delimiter, inter-frame gap ஆகியவையும் transmission நேரம் எடுத்துக்கொள்ளும். Capture-ல் FCS, physical framing அடிக்கடி இருக்காது. VLAN tag கூடுதல் bytes சேர்க்கும்; segmentation, checksum offloads காரணமாக host capture-க்கும் கம்பியில் சென்ற packets-க்கும் வேறுபாடு வரலாம்.'}},
      {heading:{en:'Wi-Fi delivers across a distribution system',ta:'Distribution system வழியாக Wi-Fi அனுப்புதல்'},body:{en:'An 802.11 data frame can distinguish radio transmitter and receiver from original source and final destination. To-DS and From-DS bits determine how address fields are interpreted; some bridging cases use four addresses. A normal unicast radio exchange can include a link-layer acknowledgement and retries, independently of TCP acknowledgement. A managed-mode interface often presents Ethernet-like packets to capture software. Inspecting actual 802.11 headers generally requires supported monitor-mode hardware and an authorized capture arrangement.',ta:'802.11 data frame-ல் radio transmitter, receiver ஆகியவை அசல் source, இறுதி destination ஆகியவற்றிலிருந்து வேறுபடலாம். To-DS, From-DS bits address fields-ன் பொருளை நிர்ணயிக்கின்றன; சில bridging சூழல்களில் நான்கு addresses உண்டு. வழக்கமான unicast radio பரிமாற்றத்தில் link-layer acknowledgement, retries வரலாம்; இவை TCP acknowledgement-க்கு வேறானவை. Managed-mode interface capture software-க்கு Ethernet போன்ற packets தரலாம். உண்மையான 802.11 headers பார்க்க ஆதரிக்கும் monitor-mode hardware-மும் அனுமதியுள்ள capture ஏற்பாடும் தேவை.'}},
      {heading:{en:'Radio efficiency depends on shared time',ta:'Radio திறன் பகிரப்படும் நேரத்தைச் சார்ந்தது'},body:{en:'Wi-Fi contends for a shared medium and generally cannot detect collisions while transmitting as wired half-duplex Ethernet once did. Backoff, inter-frame spacing, acknowledgements, aggregation, and retries affect useful throughput. Wider channels can increase potential rate but also consume more spectrum; interference and regulatory constraints matter. RSSI describes received power, whereas signal-to-noise ratio compares signal with noise. A strong signal can still coexist with heavy channel utilization, hidden stations, or a slow client consuming disproportionate airtime.',ta:'Wi-Fi பகிரப்பட்ட medium-க்காகப் போட்டியிடுகிறது; பழைய wired half-duplex Ethernet போல அனுப்பும்போதே collision கண்டறிவது பொதுவாக இயலாது. Backoff, frame இடைவெளிகள், acknowledgements, aggregation, retries ஆகியவை useful throughput-ஐ மாற்றும். அகலமான channel அதிக rate தரலாம்; ஆனால் spectrum அதிகம் தேவை, interference மற்றும் உள்ளூர் விதிகளும் முக்கியம். RSSI பெறப்பட்ட signal power; signal-to-noise ratio அதனை noise உடன் ஒப்பிடுகிறது. வலுவான signal இருந்தாலும் channel நெரிசல், மறைந்த stations அல்லது மெதுவான client airtime-ஐ அதிகம் பயன்படுத்துவது தொடரலாம்.'}}
    ],
    example:{en:'Ignoring higher-layer overhead, a 1500-byte Ethernet payload uses 1518 frame bytes plus eight bytes of preamble/start delimiter and twelve byte-times of gap: 1538 byte-times. At 1 Gbit/s that occupies 12.304 microseconds. This calculation is not a Wi-Fi throughput formula. On radio, if one attempt occupies 1 ms and a retry occupies another 1 ms, those two attempts consume 2 ms before later contention and acknowledgements are considered.',ta:'மேல்நிலை overhead தவிர்த்தால் 1500-byte Ethernet payload-க்கு 1518 frame bytes, எட்டு preamble/start delimiter bytes, பன்னிரண்டு byte-times gap சேர்ந்து 1538 byte-times தேவை. 1 Gbit/s-ல் இது 12.304 microseconds. இதை Wi-Fi throughput சூத்திரமாகப் பயன்படுத்த முடியாது. Radio-வில் முதல் முயற்சி 1 ms, retry மேலும் 1 ms எடுத்தால் contention, acknowledgements சேர்ப்பதற்குமுன்பே 2 ms செலவாகிறது.'},
    failure:{en:'A nearby client reports excellent RSSI but poor video quality during busy hours. Check airtime utilization, retry counts, channel overlap, and competing traffic before increasing transmit power. Increasing power on only the AP can worsen asymmetry because the client may still transmit weakly.',ta:'AP அருகிலுள்ள client-க்கு RSSI சிறப்பாக இருந்தும் நெரிசல் நேரத்தில் video பாதிக்கிறது. Transmit power அதிகரிக்கும்முன் airtime பயன்பாடு, retry எண்ணிக்கை, channel overlap, போட்டி traffic ஆகியவற்றைப் பார்க்கவும். AP power மட்டும் உயர்த்தினால் client பதில் பலவீனமாகவே இருந்து இருதிசை சமநிலை மோசமாகலாம்.'},
    lab:{commands:"python3 - <<'PY'\npayload=1500\nframe=14+payload+4\nwire=frame+8+12\nprint('frame_bytes',frame)\nprint('wire_microseconds_at_1Gbps',wire*8/1000)\nprint('payload_fraction',round(payload/wire,4))\nPY\nip -s link",guidance:{en:'Run on Linux with Python 3 and iproute2. Read local counters only; their meanings depend on the driver and they do not directly count all Wi-Fi retries.',ta:'Linux-ல் Python 3, iproute2 கொண்டு இயக்கவும். உள்ளூர் counters மட்டும் படிக்கப்படும்; driver-ஐச் சார்ந்த இவை எல்லா Wi-Fi retries-ஐயும் நேரடியாக எண்ணாது.'},expected:{en:'The calculation prints 1518 frame bytes, 12.304 microseconds, and about 0.9753 payload fraction. Interface counters may include virtual devices.',ta:'1518 frame bytes, 12.304 microseconds, சுமார் 0.9753 payload fraction வரும். Interface counters-ல் virtual devices-மும் இருக்கலாம்.'},cleanup:{en:'No interfaces, capture modes, files, or radio settings are changed.',ta:'Interfaces, capture modes, files, radio settings எதுவும் மாற்றப்படாது; cleanup தேவையில்லை.'}},
    questions:[
      {question:{en:'How much wire time does the example consume at 1 Gbit/s?',ta:'எடுத்துக்காட்டு 1 Gbit/s-ல் எவ்வளவு wire நேரம் எடுக்கும்?'},options:{en:['12.304 microseconds','1.538 seconds','Exactly 12 microseconds including all overhead'],ta:['12.304 microseconds','1.538 seconds','எல்லா overhead உட்பட சரியாக 12 microseconds']},answer:0,explanation:{en:'1538 byte-times multiplied by eight bits and divided by one billion gives 12.304 microseconds.',ta:'1538 byte-times-ஐ எட்டு bits-ஆல் பெருக்கி ஒரு பில்லியனால் வகுத்தால் 12.304 microseconds.'}},
      {question:{en:'Does an 802.11 ACK confirm TCP application delivery?',ta:'802.11 ACK என்பது TCP application delivery உறுதியா?'},options:{en:['No, it acknowledges a local radio exchange','Yes, it replaces all TCP ACKs','Yes, it proves the remote server read the bytes'],ta:['இல்லை; அது உள்ளூர் radio பரிமாற்றத்துக்கானது','ஆம்; எல்லா TCP ACK-களையும் மாற்றுகிறது','ஆம்; remote server bytes படித்ததை உறுதிப்படுத்துகிறது']},answer:0,explanation:{en:'Link-layer reception and end-to-end transport progress are separate events.',ta:'Link-layer பெறுதலும் end-to-end transport முன்னேற்றமும் தனித்தனி நிகழ்வுகள்.'}},
      {question:{en:'Strong RSSI with busy-hour stalls suggests checking what next?',ta:'நல்ல RSSI இருந்தும் நெரிசல் நேரத் தடை வந்தால் அடுத்து எதைப் பார்ப்பது?'},options:{en:['Channel utilization and retries','Only the hostname spelling','Only increasing AP power'],ta:['Channel பயன்பாடு, retries','Hostname எழுத்தை மட்டும்','AP power உயர்த்துவதை மட்டும்']},answer:0,explanation:{en:'Received power alone does not describe contention, interference, or airtime efficiency.',ta:'பெறப்பட்ட power மட்டும் contention, interference, airtime திறனை விளக்காது.'}}
    ],refs:[['IEEE 802.3 Ethernet working group','https://www.ieee802.org/3/'],['IEEE 802.11 wireless LAN working group','https://www.ieee802.org/11/'],['Linux segmentation offloads','https://docs.kernel.org/networking/segmentation-offloads.html']]
  },
  {
    id:33,module:8,model:'switch',
    title:{en:'STP, RSTP, and LACP failure reasoning',ta:'STP, RSTP, LACP செயல்முறையும் கோளாறு ஆய்வும்'},
    summary:{en:'Distinguish loop prevention from link aggregation and predict why redundancy may preserve connectivity without doubling one flow’s throughput.',ta:'Loop தடுப்பையும் link aggregation-ஐயும் வேறுபடுத்தி, redundant links தொடர்பைக் காத்தாலும் ஒரு flow-ன் வேகம் ஏன் இரட்டிப்பாகாது என்று விளக்குவோம்.'},
    prerequisites:{en:'Ethernet flooding, MAC learning, VLAN trunks, and full-duplex links.',ta:'Ethernet flooding, MAC learning, VLAN trunks, full-duplex links பற்றித் தெரிந்திருக்க வேண்டும்.'},
    objectives:{en:['Explain root election and blocked alternatives.','Compare RSTP synchronization with classic STP timers.','Predict aggregate capacity and individual-flow limits under LACP.'],ta:['Root election, தடுக்கப்பட்ட மாற்றுப்பாதைகள் விளக்குதல்.','RSTP synchronization-ஐ பழைய STP timers உடன் ஒப்பிடுதல்.','LACP-ல் மொத்த capacity மற்றும் தனி flow வரம்பைக் கணித்தல்.']},
    sections:[
      {heading:{en:'A redundant graph needs an active tree',ta:'Redundant graph-க்கு செயல்படும் tree தேவை'},body:{en:'Ethernet flooding around a physical loop can multiply frames because ordinary bridging does not decrement an IP-style hop counter. STP exchanges BPDUs, elects a root bridge using the lowest bridge identifier, and selects forwarding paths using path costs and tie-breakers. Some ports remain non-forwarding for user traffic while preserving an alternate path. Root placement should be intentional: an accidental low-priority bridge can redirect traffic through an unsuitable part of the network.',ta:'சாதாரண bridging-ல் IP போல hop counter குறையாததால் physical loop வழியாக flood ஆகும் Ethernet frames பெருகலாம். STP, BPDUs பரிமாறி மிகக் குறைந்த bridge identifier கொண்ட root bridge-ஐத் தேர்ந்தெடுக்கிறது; path cost, tie-breakers அடிப்படையில் forwarding பாதைகள் அமைகின்றன. சில ports user traffic அனுப்பாமல் மாற்றுப்பாதையாக இருக்கும். Root இடத்தைத் திட்டமிட வேண்டும்; தற்செயலாக முன்னுரிமை பெற்ற bridge பொருத்தமற்ற பாதைக்கு traffic-ஐ மாற்றலாம்.'}},
      {heading:{en:'Rapid convergence has prerequisites',ta:'விரைவான convergence-க்கும் நிபந்தனைகள் உண்டு'},body:{en:'RSTP uses discarding, learning, and forwarding states, and roles including root, designated, and alternate. Proposal/agreement exchanges can accelerate transitions on suitable point-to-point links. Edge ports may forward rapidly because they are expected to attach endpoints, but attaching another bridge invalidates that assumption. Compatibility with older STP and actual topology affect convergence. BPDU guard and root guard address different mistakes; they are operational controls rather than substitutes for understanding where bridges are connected.',ta:'RSTP-ல் discarding, learning, forwarding states மற்றும் root, designated, alternate roles உள்ளன. பொருத்தமான point-to-point links-ல் proposal/agreement பரிமாற்றம் transition-ஐ விரைவாக்கும். Endpoint இணையும் என்ற எதிர்பார்ப்பால் edge port விரைவில் forward செய்யலாம்; அங்கே bridge இணைத்தால் அந்த அடிப்படை தவறாகும். பழைய STP compatibility, உண்மையான topology ஆகியவை convergence-ஐ மாற்றும். BPDU guard, root guard வெவ்வேறு தவறுகளைத் தடுக்கின்றன; bridge இணைப்பைப் புரிந்துகொள்வதற்கு இவை மாற்றாகாது.'}},
      {heading:{en:'LACP coordinates one logical link',ta:'LACP ஒரே logical link-ஐ ஒருங்கிணைக்கிறது'},body:{en:'Link aggregation groups compatible physical links into a logical connection. LACP exchanges actor and partner information so members can agree on aggregation and collecting/distributing state. It does not automatically make two independent switches one aggregation partner; multi-chassis designs need additional coordination. Traffic distribution commonly hashes a flow to one member to preserve ordering. STP normally sees the aggregate as a logical port, while a mismatched static bundle can create loss or loops instead of resilience.',ta:'Link aggregation பொருந்தக்கூடிய physical links-ஐ ஒரே logical இணைப்பாகக் கூட்டுகிறது. LACP actor, partner தகவல் பரிமாறி aggregation மற்றும் collecting/distributing நிலைகளை ஒத்திசைக்கிறது. தனித்தனி இரண்டு switches தானாக ஒரே partner ஆகாது; multi-chassis வடிவமைப்புக்கு கூடுதல் ஒருங்கிணைப்பு வேண்டும். வரிசை மாறாமல் இருக்க பொதுவாக flow hash மூலம் ஒரு member-க்கு traffic ஒதுக்கப்படும். STP aggregate-ஐ logical port ஆகக் காணும்; தவறாக அமைந்த static bundle நம்பகத்தன்மைக்குப் பதிலாக loss அல்லது loops ஏற்படுத்தலாம்.'}}
    ],
    example:{en:'Two switches have two 1 Gbit/s members in an LACP bundle. Four independent flows can potentially share both members, but one flow pinned by hashing is normally limited to one member’s line rate before overhead. If one member fails, the remaining member can carry the traffic at reduced aggregate capacity. In a separate three-switch triangle, STP blocks a redundant logical path; adding links alone does not imply every path forwards simultaneously.',ta:'இரு switches இடையில் LACP bundle-ல் இரண்டு 1 Gbit/s members உள்ளன. நான்கு தனி flows இரண்டிலும் பகிரப்படலாம்; hash மூலம் ஒரே member-ல் இருக்கும் ஒரு flow பொதுவாக overhead-க்கு முன்பே அதன் line rate-க்கு மட்டுப்படும். ஒரு member செயலிழந்தால் மற்றது குறைந்த மொத்த capacity-யுடன் traffic எடுத்துச் செல்லும். மூன்று-switch triangle-ல் STP ஒரு redundant logical பாதையைத் தடுக்கும்; links சேர்த்ததாலேயே எல்லாப் பாதைகளும் ஒரே நேரத்தில் forward செய்யாது.'},
    failure:{en:'Both LACP endpoints configured passive may never initiate negotiation. If a member stays detached, inspect actor/partner identity, active/passive settings, speed, VLAN consistency, and collecting/distributing state. Do not disable spanning tree merely because a redundant cable appears blocked; that may be the mechanism preventing a broadcast storm.',ta:'இருபுற LACP-யும் passive என்றால் negotiation தொடங்காமலிருக்கலாம். Member சேராவிட்டால் actor/partner identity, active/passive அமைப்பு, speed, VLAN ஒற்றுமை, collecting/distributing நிலை பார்க்கவும். Redundant cable blocked என்று மட்டும் STP-ஐ நிறுத்த வேண்டாம்; அதுவே broadcast storm-ஐத் தடுத்துக்கொண்டிருக்கலாம்.'},
    lab:{commands:'ip -d link show type bridge\nbridge link show\nbridge vlan show\npython3 - <<\'PY\'\nrates=[1_000_000_000,1_000_000_000]\nprint("aggregate_Gbps",sum(rates)/1e9)\nprint("one_member_Gbps",max(rates)/1e9)\nPY',guidance:{en:'Use Linux iproute2 and Python 3. Inspect existing bridges without creating any. Empty bridge listings are valid on hosts without bridges.',ta:'Linux iproute2, Python 3 பயன்படுத்தவும். Bridge உருவாக்காமல் ஏற்கெனவே இருப்பவற்றைப் பார்க்கவும். Bridge இல்லாத host-ல் காலியான பட்டியல் வருவது இயல்பு.'},expected:{en:'The calculation prints 2 Gbit/s aggregate and 1 Gbit/s member capacity. Bridge output reflects local state, not an inferred external STP topology.',ta:'கணக்கில் aggregate 2 Gbit/s, member 1 Gbit/s வரும். Bridge வெளியீடு உள்ளூர் நிலையை மட்டுமே காட்டும்; வெளியிலுள்ள STP topology-ஐ ஊகிக்காது.'},cleanup:{en:'No resources are created and no spanning-tree or bond settings are changed.',ta:'எந்த resource-மும் உருவாகாது; spanning-tree அல்லது bond settings மாற்றமில்லை.'}},
    questions:[
      {question:{en:'Why can one flow remain near 1 Gbit/s on a two-member 2 Gbit/s bundle?',ta:'2 Gbit/s இரு-member bundle-ல் ஒரு flow ஏன் 1 Gbit/s அருகில் நிற்கலாம்?'},options:{en:['Flow hashing selects one member','LACP encrypts half the bytes','STP always disables every second member'],ta:['Flow hashing ஒரு member-ஐத் தேர்கிறது','LACP பாதி bytes-ஐ encrypt செய்கிறது','STP எப்போதும் இரண்டாவது member-ஐ நிறுத்துகிறது']},answer:0,explanation:{en:'Keeping one flow on one member usually preserves order; aggregate capacity is shared across flows.',ta:'ஒரு flow ஒரே member-ல் இருப்பது வரிசையைக் காக்கும்; aggregate capacity பல flows இடையே பகிரப்படும்.'}},
      {question:{en:'Which identifier wins an STP root election?',ta:'STP root election-ல் எந்த identifier வெல்லும்?'},options:{en:['Lowest bridge identifier','Highest TCP port','Longest hostname'],ta:['மிகக் குறைந்த bridge identifier','மிக அதிக TCP port','நீளமான hostname']},answer:0,explanation:{en:'Bridge priority and identifier components determine the ordering, not application information.',ta:'Bridge priority மற்றும் identifier கூறுகளே வரிசையை நிர்ணயிக்கும்; application தகவல் அல்ல.'}},
      {question:{en:'Both peers are LACP passive and no bundle forms. What should be checked?',ta:'இருபுறமும் LACP passive; bundle உருவாகவில்லை. எதைச் சரிபார்ப்பது?'},options:{en:['Enable initiation on an appropriate peer after reviewing configuration','Remove all loop prevention immediately','Increase DNS TTL'],ta:['அமைப்பை ஆய்ந்து பொருத்தமான peer-ல் initiation அமைத்தல்','உடனே எல்லா loop தடுப்பையும் நீக்குதல்','DNS TTL உயர்த்துதல்']},answer:0,explanation:{en:'At least one active participant initiates LACP; passive/passive is a negotiation problem.',ta:'குறைந்தது ஒரு active participant LACP தொடங்க வேண்டும்; passive/passive negotiation சிக்கல்.'}}
    ],refs:[['IEEE bridges and bridged networks','https://standards.ieee.org/ieee/802.1Q/10323/'],['IEEE link aggregation','https://standards.ieee.org/ieee/802.1AX/6768/'],['Linux bonding','https://docs.kernel.org/networking/bonding.html']]
  },
  {
    id:34,module:8,model:'ipv6',
    title:{en:'IPv6 coexistence, NAT64, and DNS64',ta:'IPv6 இணைவாழ்வு, NAT64, DNS64'},
    summary:{en:'Compare dual stack, tunnels, and translation, then follow an IPv6-only client reaching an IPv4-only service through separate DNS and packet-processing functions.',ta:'Dual stack, tunnels, translation ஆகியவற்றை ஒப்பிட்டு, IPv6-only client ஒரு IPv4-only service-ஐ தனித்தனி DNS மற்றும் packet செயல்முறைகள் வழியாக அடைவதைப் பின்தொடர்வோம்.'},
    prerequisites:{en:'IPv6 addressing, DNS A/AAAA records, routing, and stateful NAT.',ta:'IPv6 addressing, DNS A/AAAA records, routing, stateful NAT தெரிந்திருக்க வேண்டும்.'},
    objectives:{en:['Separate DNS synthesis from address translation.','Calculate a /96 embedded IPv4 destination.','Recognize DNSSEC and literal-address limitations.'],ta:['DNS உருவாக்கத்தையும் address translation-ஐயும் பிரித்தறிதல்.','/96 prefix-ல் IPv4 destination இணைத்துக் கணக்கிடுதல்.','DNSSEC, literal address வரம்புகளை அறிதல்.']},
    sections:[
      {heading:{en:'Three coexistence tools solve different problems',ta:'மூன்று coexistence முறைகளின் வேறுபட்ட பணிகள்'},body:{en:'Dual stack gives a host both IPv4 and IPv6 connectivity, with applications choosing among usable addresses. A tunnel carries one network protocol inside another and needs working endpoints and adequate underlay MTU. Translation changes packet representation between address families. None of these automatically repairs missing routes, policy blocks, or application assumptions. Native IPv6 destinations should remain reachable natively where possible rather than being translated unnecessarily. Operational plans must cover DNS, return traffic, logging, and capacity, not just address assignment.',ta:'Dual stack host-க்கு IPv4, IPv6 இரண்டின் தொடர்பையும் தருகிறது; applications பயன்படுத்தக்கூடிய address-ஐத் தேர்கின்றன. Tunnel ஒரு protocol-ஐ மற்றொன்றுக்குள் எடுத்துச் செல்லும்; இயங்கும் endpoints, போதிய underlay MTU வேண்டும். Translation address families இடையே packet வடிவத்தை மாற்றுகிறது. இம்முறைகள் missing routes, policy தடைகள், application ஊகங்களைத் தானாகச் சரிசெய்யாது. இயன்றவரை native IPv6 destination-ஐ native வழியே அடைய வேண்டும். திட்டத்தில் DNS, return traffic, logging, capacity ஆகியவையும் இருக்க வேண்டும்.'}},
      {heading:{en:'DNS64 supplies an address; NAT64 moves packets',ta:'DNS64 address தருகிறது; NAT64 packets நகர்த்துகிறது'},body:{en:'DNS64 can synthesize an AAAA answer from an A record when a suitable native AAAA answer is absent. With a /96 translation prefix, the IPv4 address occupies the low 32 bits. Routing sends that synthetic destination toward a NAT64 translator. Stateful NAT64 maintains transport mappings and uses an IPv4 source address and port on the IPv4 side. DNS64 is not the translator: successful name resolution without a working route and translator still leaves the service unreachable.',ta:'பொருத்தமான native AAAA இல்லாதபோது DNS64, A record-லிருந்து AAAA பதிலை உருவாக்கலாம். /96 translation prefix-ல் கடைசி 32 bits-ல் IPv4 address இருக்கும். Routing அந்த synthetic destination-ஐ NAT64 translator-க்கு அனுப்பும். Stateful NAT64 transport mappings வைத்திருந்து IPv4 பக்கத்தில் IPv4 source address, port பயன்படுத்தும். DNS64 தானே translator அல்ல; DNS பதில் கிடைத்தாலும் route, translator இயங்காவிட்டால் service கிடைக்காது.'}},
      {heading:{en:'Applications and validation expose the boundaries',ta:'Applications, validation காட்டும் வரம்புகள்'},body:{en:'An application using an IPv4 literal bypasses ordinary AAAA synthesis. 464XLAT adds a client-side translation function for some such IPv4-dependent applications, alongside provider-side translation. DNSSEC validation needs deliberate placement because a synthesized AAAA is not an authoritative signed AAAA RRset. A validating host and a DNS64 resolver cannot simply ignore that difference. Translation also consumes mapping capacity and may struggle with protocols embedding addresses in payloads. ICMP translation and path MTU handling remain necessary for reliable large transfers.',ta:'IPv4 literal பயன்படுத்தும் application வழக்கமான AAAA உருவாக்கத்தைத் தவிர்க்கிறது. இத்தகைய சில IPv4 சார்ந்த applications-க்கு 464XLAT client-side translation-ஐ provider-side translation உடன் சேர்க்கிறது. உருவாக்கிய AAAA என்பது authoritative signed AAAA RRset அல்ல என்பதால் DNSSEC validation எங்கே நடக்கிறது என்று திட்டமிட வேண்டும். Validating host, DNS64 resolver இந்த வேறுபாட்டைப் புறக்கணிக்க முடியாது. Mapping capacity தேவை; payload-ல் addresses எழுதும் protocols சிக்கலாகலாம். பெரிய transfers-க்கு ICMP translation, path MTU கையாளுதலும் அவசியம்.'}}
    ],
    example:{en:'For arithmetic, embed documentation address 192.0.2.33 in 64:ff9b::/96. The bytes c0 00 02 21 yield 64:ff9b::c000:221. An IPv6-only client sends toward that synthetic address; a configured translator maps it to IPv4 destination 192.0.2.33 and records return state. This is a representation exercise, not a claim that documentation space is reachable or that this prefix is suitable for every private-address scenario.',ta:'கணக்குப் பயிற்சிக்காக documentation address 192.0.2.33-ஐ 64:ff9b::/96-ல் இணைப்போம். c0 00 02 21 bytes மூலம் 64:ff9b::c000:221 கிடைக்கும். IPv6-only client இதற்கு அனுப்பும்; அமைக்கப்பட்ட translator IPv4 destination 192.0.2.33 ஆக மாற்றி return state வைக்கும். இது வடிவமாற்றப் பயிற்சி மட்டுமே; documentation இடம் reachable என்றோ எல்லா private address சூழலுக்கும் இப்பrefix பொருந்தும் என்றோ அர்த்தமில்லை.'},
    failure:{en:'A hostname works but an application hard-coded to an IPv4 literal fails on an IPv6-only network. Compare the address family requested by each application before blaming DNS. A second failure pattern is successful synthetic resolution with repeated connection timeouts because the NAT64 prefix is not routed to the translator.',ta:'Hostname வழியாக இயங்கியும் IPv4 literal பதித்த application IPv6-only network-ல் தோற்கிறது. DNS-ஐக் குறைசொல்லும்முன் ஒவ்வொரு application கேட்கும் address family-ஐப் பார்க்கவும். மற்றொரு கோளாறு: synthetic DNS பதில் கிடைத்தும் NAT64 prefix translator-க்கு route ஆகாததால் connection timeout வருவது.'},
    lab:{commands:"python3 - <<'PY'\nimport ipaddress\np=ipaddress.IPv6Network('64:ff9b::/96')\nv=ipaddress.IPv4Address('192.0.2.33')\na=ipaddress.IPv6Address(int(p.network_address)|int(v))\nprint(a)\nprint(ipaddress.IPv4Address(int(a)&0xffffffff))\nPY",guidance:{en:'This Python 3 calculation does not require IPv6 connectivity or a NAT64 deployment. It models only /96 embedding; other supported prefix lengths use different placement rules.',ta:'இந்த Python 3 கணக்குக்கு IPv6 தொடர்போ NAT64 அமைப்போ தேவையில்லை. /96 இணைப்பை மட்டும் காட்டுகிறது; மற்ற prefix நீளங்களில் இடமிடும் விதி வேறுபடும்.'},expected:{en:'Output is 64:ff9b::c000:221 followed by 192.0.2.33. No DNS synthesis or translation service is actually started.',ta:'64:ff9b::c000:221, பின்னர் 192.0.2.33 வரும். உண்மையான DNS synthesis அல்லது translation service தொடங்கப்படாது.'},cleanup:{en:'The interpreter exits; there are no created resources or settings to restore.',ta:'Interpreter முடியும்; உருவாக்கப்பட்ட resources அல்லது மீட்டமைக்க வேண்டிய settings இல்லை.'}},
    questions:[
      {question:{en:'Which function synthesizes AAAA records?',ta:'எந்தச் செயல் AAAA records உருவாக்குகிறது?'},options:{en:['DNS64','Stateful NAT64 packet mapping','Ethernet FCS'],ta:['DNS64','Stateful NAT64 packet mapping','Ethernet FCS']},answer:0,explanation:{en:'DNS64 changes DNS answers; NAT64 handles translated traffic and, in the stateful case, mappings.',ta:'DNS64 DNS பதிலை மாற்றுகிறது; NAT64 traffic translation மற்றும் stateful mappings கையாளுகிறது.'}},
      {question:{en:'Which address embeds 192.0.2.33 in the example /96?',ta:'எடுத்துக்காட்டு /96-ல் 192.0.2.33 இணைந்த address எது?'},options:{en:['64:ff9b::c000:221','64:ff9b::192:33','192.0.2.33::64'],ta:['64:ff9b::c000:221','64:ff9b::192:33','192.0.2.33::64']},answer:0,explanation:{en:'Convert each IPv4 octet to hexadecimal bytes: c0, 00, 02, 21.',ta:'ஒவ்வொரு IPv4 octet-ஐ hexadecimal byte ஆக்கினால் c0, 00, 02, 21.'}},
      {question:{en:'Synthetic AAAA resolves but all connections time out. What is a useful next check?',ta:'Synthetic AAAA கிடைத்தும் connections timeout. அடுத்த பயனுள்ள சோதனை எது?'},options:{en:['Route to the translation prefix and translator state','Assume DNSSEC encrypts the connection','Replace all IPv6 addresses with MAC addresses'],ta:['Translation prefix route, translator state','DNSSEC connection-ஐ encrypt செய்கிறது என நினைத்தல்','எல்லா IPv6 addresses-ஐ MAC addresses ஆக மாற்றுதல்']},answer:0,explanation:{en:'The DNS and packet paths are independent stages; successful synthesis does not establish forwarding.',ta:'DNS, packet பாதைகள் தனித்தனி படிகள்; synthesis வெற்றி forwarding-ஐ உறுதிப்படுத்தாது.'}}
    ],refs:[['IPv6 translation address format','https://www.rfc-editor.org/rfc/rfc6052.html'],['Stateful NAT64','https://www.rfc-editor.org/rfc/rfc6146.html'],['DNS64','https://www.rfc-editor.org/rfc/rfc6147.html'],['464XLAT','https://www.rfc-editor.org/rfc/rfc6877.html']]
  },
  {
    id:35,module:9,model:'tcp-loss',
    title:{en:'TCP RTT estimation, RTO, and selective acknowledgement',ta:'TCP RTT மதிப்பீடு, RTO, selective acknowledgement'},
    summary:{en:'Compute a retransmission timer from measured delay and variation, then use cumulative ACK and SACK evidence to distinguish a missing segment from a missing application message.',ta:'அளந்த delay, variation மூலம் retransmission timer கணக்கிட்டு, cumulative ACK, SACK சான்றுகளால் காணாமல் போன segment-ஐ application message பிரச்சினையிலிருந்து வேறுபடுத்துவோம்.'},
    prerequisites:{en:'TCP byte sequence numbers, acknowledgements, windows, and retransmission.',ta:'TCP byte sequence numbers, acknowledgements, windows, retransmission தெரிந்திருக்க வேண்டும்.'},
    objectives:{en:['Update SRTT and RTTVAR in the correct order.','Explain timeout backoff and ambiguous RTT samples.','Interpret SACK blocks without advancing cumulative delivery across a gap.'],ta:['SRTT, RTTVAR-ஐ சரியான வரிசையில் புதுப்பித்தல்.','Timeout backoff, தெளிவற்ற RTT samples விளக்குதல்.','Gap இருக்கும்போது cumulative delivery நகராமல் SACK blocks புரிந்துகொள்ளுதல்.']},
    sections:[
      {heading:{en:'A timer needs an uncertainty margin',ta:'Timer-க்கு uncertainty இடைவெளி தேவை'},body:{en:'RFC 6298 initializes the smoothed RTT to the first valid sample R and RTT variation to R/2. For later samples, variation uses the difference between the old smoothed RTT and the new measurement before the smoothed value is updated. With alpha 1/8 and beta 1/4, recent measurements influence rather than completely replace history. RTO combines SRTT with the larger of clock granularity and four times RTTVAR, then applies the specified lower bound.',ta:'RFC 6298 முதல் செல்லுபடியான sample R-ஐ smoothed RTT ஆகவும் R/2-ஐ RTT variation ஆகவும் தொடங்குகிறது. அடுத்த sample-ல் smoothed மதிப்பைப் புதுப்பிக்கும்முன் பழைய SRTT-க்கும் புதிய அளவுக்கும் உள்ள வேறுபாட்டால் variation கணக்கிட வேண்டும். Alpha 1/8, beta 1/4 காரணமாக புதிய அளவு பழைய வரலாற்றை முழுவதும் மாற்றாது. SRTT உடன் clock granularity அல்லது நான்கு மடங்கு RTTVAR-ல் பெரியதைச் சேர்த்து RTO பெறப்படுகிறது; பிறகு குறைந்தபட்ச வரம்பு பொருந்தும்.'}},
      {heading:{en:'Retransmission makes measurement ambiguous',ta:'Retransmission அளவீட்டில் குழப்பம் தரலாம்'},body:{en:'After retransmission, a returning ACK may correspond to the original transmission or its replacement. Karn’s rule avoids ordinary RTT sampling from such ambiguous exchanges unless a mechanism such as timestamps disambiguates them. A retransmission timeout triggers timer backoff, normally doubling the RTO. A timeout is distinct from faster loss recovery driven by ACK evidence. Implementations may have additional recovery mechanisms, so a packet trace should not assume every retransmission waited for an RTO.',ta:'Retransmission பிறகு வரும் ACK அசல் அனுப்புதலுக்கா மாற்று அனுப்புதலுக்கா என்பது தெளிவில்லாமல் இருக்கலாம். Timestamps போன்ற முறையால் பிரித்தறிய முடியாவிட்டால் Karn விதி இத்தகைய exchange-லிருந்து சாதாரண RTT sample எடுப்பதைத் தவிர்க்கிறது. Retransmission timeout RTO-ஐ பொதுவாக இரட்டிப்பாக்கும் backoff தரும். ACK சான்றால் வேகமாக நடக்கும் loss recovery வேறு. Implementation-ல் கூடுதல் recovery முறைகள் இருக்கலாம்; ஒவ்வொரு retransmission-மும் RTO வரை காத்தது என்று trace-ல் ஊகிக்கக்கூடாது.'}},
      {heading:{en:'SACK describes received ranges beyond a gap',ta:'Gap-க்கு அப்பால் பெற்ற வரம்புகளை SACK காட்டும்'},body:{en:'A cumulative ACK identifies the next byte needed for a contiguous stream. Negotiated SACK adds blocks describing noncontiguous ranges already received; each block uses a left edge and an exclusive right edge. The sender maintains recovery information to avoid needlessly retransmitting every later byte. SACK does not create independent application streams and does not acknowledge missing bytes. Receiver memory pressure can also affect retained out-of-order data, so a sender must still preserve data until cumulatively acknowledged.',ta:'Cumulative ACK தொடர்ச்சியான stream-ல் அடுத்து தேவைப்படும் byte-ஐக் குறிக்கிறது. ஒப்புக்கொள்ளப்பட்ட SACK, ஏற்கெனவே பெற்ற தொடர்ச்சியற்ற வரம்புகளை left edge, சேராத right edge மூலம் காட்டும். பின்னுள்ள எல்லா bytes-ஐயும் தேவையின்றி மீண்டும் அனுப்பாமல் sender recovery தகவல் வைக்கும். SACK தனி application streams உருவாக்காது; காணாமல் போன bytes பெற்றதாகச் சொல்லாது. Receiver memory அழுத்தத்தால் out-of-order data தக்கவைத்தல் மாறலாம்; cumulative ACK வரும்வரை sender data-ஐ வைத்திருக்க வேண்டும்.'}}
    ],
    example:{en:'Start with an RTT sample of 100 ms: SRTT=100 and RTTVAR=50. A second sample of 140 ms gives RTTVAR=0.75×50+0.25×40=47.5 ms, then SRTT=105 ms. The raw timer is 295 ms when clock granularity is small, but RFC 6298 recommends rounding an RTO below one second up to one second. Separately, ACK 2000 with SACK [3000,4000) says bytes 2000–2999 are still missing while 3000–3999 arrived.',ta:'முதல் RTT sample 100 ms என்றால் SRTT=100, RTTVAR=50. அடுத்தது 140 ms என்றால் RTTVAR=0.75×50+0.25×40=47.5 ms; பின்னர் SRTT=105 ms. Clock granularity சிறியதாக இருந்தால் raw timer 295 ms; ஆனால் ஒரு second-க்குக் குறைந்த RTO-ஐ ஒரு second ஆக உயர்த்த RFC 6298 பரிந்துரைக்கிறது. தனியாக ACK 2000, SACK [3000,4000) என்றால் 2000–2999 இன்னும் வரவில்லை; 3000–3999 வந்துள்ளன.'},
    failure:{en:'A rushed implementation updates SRTT before RTTVAR and obtains a smaller uncertainty estimate. It may retransmit too eagerly on variable-delay paths. Diagnose by replaying known samples through the formulas, then compare with implementation-specific timer floors rather than treating the RFC example as every operating system’s exact default.',ta:'அவசரமாக எழுதப்பட்ட implementation RTTVAR-க்கு முன் SRTT புதுப்பித்து uncertainty-ஐக் குறைவாக மதிப்பிடுகிறது. Delay மாறும் பாதையில் தேவையற்ற retransmission வரலாம். தெரிந்த samples-ஐ சூத்திரத்தில் மீண்டும் செலுத்திப் பார்த்து, பின்னர் implementation timer floor-ஐ ஒப்பிட வேண்டும்; RFC எடுத்துக்காட்டே எல்லா OS-ன் default அல்ல.'},
    lab:{commands:"python3 - <<'PY'\nsrtt=100.0\nvar=50.0\nr=140.0\nvar=.75*var+.25*abs(srtt-r)\nsrtt=.875*srtt+.125*r\nraw=srtt+max(1.0,4*var)\nprint('SRTT_ms',srtt,'RTTVAR_ms',var)\nprint('raw_RTO_ms',raw,'RFC_example_RTO_ms',max(1000,raw))\nPY\nss -ti",guidance:{en:'Run the local Python calculation and optionally inspect your own Linux sockets with ss. An idle machine may have no established TCP entries.',ta:'உள்ளூர் Python கணக்கை இயக்கி Linux ss மூலம் உங்கள் sockets-ஐப் பார்க்கலாம். Traffic இல்லாத கணினியில் established TCP பதிவுகள் இல்லாமலும் இருக்கலாம்.'},expected:{en:'The values are 105, 47.5, 295, and 1000 ms. Socket RTT units and timer behavior depend on the installed tools and kernel.',ta:'105, 47.5, 295, 1000 ms மதிப்புகள் வரும். Socket RTT units, timer நடத்தை நிறுவிய tools, kernel-ஐச் சாரும்.'},cleanup:{en:'Nothing is created; existing sockets are only inspected.',ta:'எதுவும் உருவாக்கப்படாது; இருக்கும் sockets மட்டும் பார்க்கப்படும்.'}},
    questions:[
      {question:{en:'What is the new RTTVAR in the worked example?',ta:'எடுத்துக்காட்டில் புதிய RTTVAR எவ்வளவு?'},options:{en:['47.5 ms','105 ms','140 ms'],ta:['47.5 ms','105 ms','140 ms']},answer:0,explanation:{en:'Use the old SRTT: 0.75×50 + 0.25×|100−140| = 47.5.',ta:'பழைய SRTT பயன்படுத்த வேண்டும்: 0.75×50 + 0.25×|100−140| = 47.5.'}},
      {question:{en:'Does SACK [3000,4000) with ACK 2000 prove byte 2500 arrived?',ta:'ACK 2000 உடன் SACK [3000,4000) வந்தால் byte 2500 வந்துவிட்டதா?'},options:{en:['No, it lies in the unresolved gap','Yes, SACK covers all earlier bytes','Yes, because the right edge is 4000'],ta:['இல்லை; அது நிரப்பப்படாத gap-ல் உள்ளது','ஆம்; SACK எல்லா முந்தைய bytes-ஐயும் உள்ளடக்கும்','ஆம்; right edge 4000 என்பதால்']},answer:0,explanation:{en:'Only the reported range is selectively acknowledged; cumulative progress still stops at 2000.',ta:'குறிப்பிட்ட வரம்பு மட்டுமே selectively acknowledged; cumulative முன்னேற்றம் 2000-ல் நிற்கிறது.'}},
      {question:{en:'Why avoid an ambiguous retransmission RTT sample?',ta:'தெளிவற்ற retransmission RTT sample-ஐ ஏன் தவிர்க்க வேண்டும்?'},options:{en:['The ACK may refer to either transmission','TCP never uses RTT','SACK encrypts timestamps'],ta:['ACK எந்த அனுப்புதலுக்கானது என்பது தெரியாது','TCP RTT பயன்படுத்தவே செய்யாது','SACK timestamps-ஐ encrypt செய்கிறது']},answer:0,explanation:{en:'An incorrectly attributed sample biases the timer; timestamps can sometimes resolve the ambiguity.',ta:'தவறாக இணைத்த sample timer-ஐத் தவறாக்கும்; timestamps சில நேரங்களில் குழப்பத்தைத் தீர்க்கும்.'}}
    ],refs:[['TCP retransmission timer','https://www.rfc-editor.org/rfc/rfc6298.html'],['TCP selective acknowledgement','https://www.rfc-editor.org/rfc/rfc2018.html'],['SACK loss recovery','https://www.rfc-editor.org/rfc/rfc6675.html']]
  },
  {
    id:36,module:9,model:'queue',
    title:{en:'CUBIC, BBR, and packet pacing',ta:'CUBIC, BBR மற்றும் packet pacing செயல்முறை'},
    summary:{en:'Compare congestion-window growth with model-based rate selection and connect pacing, bandwidth-delay product, and queue delay without assuming a universally superior algorithm.',ta:'Congestion window வளர்ச்சியையும் model அடிப்படையிலான rate தேர்வையும் ஒப்பிட்டு, pacing, bandwidth-delay product, queue delay தொடர்பைப் புரிந்துகொள்வோம்; எல்லாச் சூழலிலும் ஒரே algorithm சிறந்தது என்று கருதமாட்டோம்.'},
    prerequisites:{en:'Congestion windows, flow control, RTT, bottlenecks, and throughput units.',ta:'Congestion window, flow control, RTT, bottleneck, throughput units தெரிந்திருக்க வேண்டும்.'},
    objectives:{en:['Describe CUBIC growth near a previous operating point.','Explain BBR bandwidth and propagation-delay estimates.','Calculate flight size and distinguish pacing from queue management.'],ta:['முந்தைய operating point அருகில் CUBIC வளர்ச்சியை விளக்குதல்.','BBR bandwidth, propagation delay மதிப்பீடுகளை விளக்குதல்.','Flight size கணக்கிட்டு pacing-ஐ queue management-லிருந்து பிரித்தறிதல்.']},
    sections:[
      {heading:{en:'CUBIC changes the window over time',ta:'CUBIC நேரத்திற்கேற்ப window மாற்றுகிறது'},body:{en:'CUBIC uses a cubic function of elapsed time to shape congestion-window growth around a remembered window from a congestion event. Growth slows near the previous operating point and becomes more aggressive farther away, with additional TCP-friendly behavior specified in the algorithm. Congestion signals still cause a response. The curve describes a window target, not a guarantee of delivery rate: receive-window limits, application pauses, RTT, recovery, and the bottleneck can all prevent a sender from realizing that target.',ta:'CUBIC congestion நிகழ்வில் நினைவில் வைத்த window-ஐச் சுற்றி காலத்தின் cubic function மூலம் congestion window வளர்ச்சியை அமைக்கிறது. பழைய operating point அருகில் வளர்ச்சி மந்தமாகி தூரத்தில் தீவிரமாகும்; TCP-friendly நடத்தையும் algorithm-ல் உள்ளது. Congestion signals-க்கு பதில் தொடரும். இந்த curve window இலக்கு மட்டுமே; delivery rate உறுதி அல்ல. Receive window வரம்பு, application இடைவெளி, RTT, recovery, bottleneck ஆகியவை இலக்கை அடையத் தடுக்கலாம்.'}},
      {heading:{en:'BBR estimates a path model',ta:'BBR பாதையின் model-ஐ மதிப்பிடுகிறது'},body:{en:'BBR estimates bottleneck delivery bandwidth and a low-delay RTT reference, then uses pacing and an in-flight bound to probe and operate the path. Delivered-rate samples can be distorted by ACK compression or application-limited sending, so sample qualification matters. BBR has multiple versions and evolving specifications; their loss responses, probing details, and coexistence behavior differ. Describe the version in any experiment. Neither BBR nor CUBIC bypasses the receiver’s advertised window or eliminates the need for loss recovery.',ta:'BBR bottleneck delivery bandwidth, குறைந்த-delay RTT அடிப்படை ஆகியவற்றை மதிப்பிட்டு pacing, in-flight வரம்பு மூலம் பாதையைச் சோதித்து இயக்குகிறது. ACK compression அல்லது application குறைந்த அளவு அனுப்புவதால் rate samples மாறலாம்; sample தகுதி முக்கியம். BBR-க்கு பல versions, வளர்ந்துவரும் specifications உள்ளன; loss response, probing, மற்ற flows உடன் பகிர்தல் வேறுபடும். ஆய்வில் version குறிப்பிட வேண்டும். BBR, CUBIC இரண்டும் receiver advertised window-ஐ மீறவோ loss recovery தேவையை நீக்கவோ செய்யாது.'}},
      {heading:{en:'Pacing controls release, not physical capacity',ta:'Pacing வெளியிடும் நேரத்தை அமைக்கும்; capacity உருவாக்காது'},body:{en:'A congestion window limits outstanding data, while pacing spaces packet release over time. Sending a whole window as a burst can overload a small downstream queue even when the average rate appears acceptable. Queue disciplines schedule traffic and may apply active queue management; they operate at a different point from the transport algorithm. Evaluate completion time, retransmissions, loaded RTT, and fairness together. A high bulk-transfer score with severely inflated interactive latency is an incomplete performance result.',ta:'Congestion window outstanding data அளவைக் கட்டுப்படுத்தும்; pacing packets வெளியிடும் இடைவெளியை அமைக்கும். சராசரி rate ஏற்றதாக இருந்தாலும் முழு window-ஐ burst ஆக அனுப்பினால் கீழ்நிலை சிறிய queue நிரம்பலாம். Queue disciplines traffic schedule செய்யும்; active queue management-மும் இருக்கலாம்; இவை transport algorithm-இலிருந்து வேறு இடத்தில் இயங்கும். Completion time, retransmissions, load உள்ள RTT, fairness அனைத்தையும் சேர்த்து மதிப்பிட வேண்டும். Bulk throughput அதிகமாக இருந்தும் interactive latency மிக உயர்ந்தால் அது முழுமையான performance முடிவு அல்ல.'}}
    ],
    example:{en:'A 100 Mbit/s bottleneck with 40 ms baseline RTT has a bandwidth-delay product of 4,000,000 bits, or 500,000 bytes. Ignoring headers, roughly that much useful data must be in flight to sustain capacity. An extra 250,000 bytes queued at that bottleneck adds about 20 ms delay. A pacer transmitting 1500-byte packets at 100 Mbit/s spaces ideal packet starts about 120 microseconds apart before accounting for framing and scheduler granularity.',ta:'100 Mbit/s bottleneck, 40 ms baseline RTT என்றால் bandwidth-delay product 4,000,000 bits, அதாவது 500,000 bytes. Headers தவிர்த்து capacity நிரம்ப இந்த அளவு useful data பாதையில் இருக்க வேண்டும். Bottleneck-ல் கூடுதலாக 250,000 bytes queue ஆனால் சுமார் 20 ms delay சேரும். 1500-byte packets-ஐ 100 Mbit/s pacer அனுப்பும்போது framing, scheduler granularity சேர்ப்பதற்குமுன் packet தொடக்க இடைவெளி சுமார் 120 microseconds.'},
    failure:{en:'An operator switches congestion control after seeing poor throughput, but the receive window was only 64 KB on a long-RTT path. The new algorithm cannot remove that flow-control ceiling. Inspect socket receive-window limits and application behavior alongside congestion state before attributing every throughput problem to congestion control.',ta:'நீண்ட RTT பாதையில் receive window 64 KB மட்டுமே இருந்தும் throughput குறைவுக்காக congestion control மாற்றப்படுகிறது. புதிய algorithm அந்த flow-control வரம்பை நீக்காது. எல்லா throughput சிக்கலையும் congestion control மீது சுமத்தும்முன் socket receive window, application நடத்தை, congestion state ஆகியவற்றைப் பார்க்க வேண்டும்.'},
    lab:{commands:"sysctl net.ipv4.tcp_available_congestion_control net.ipv4.tcp_congestion_control\ntc qdisc show\npython3 - <<'PY'\nrate=100_000_000\nrtt=.040\nprint('BDP_bytes',rate*rtt/8)\nprint('extra_queue_ms',250_000*8/rate*1000)\nprint('packet_spacing_us',1500*8/rate*1e6)\nPY",guidance:{en:'Use Linux read-only sysctl and tc inspection plus Python 3. Available algorithms are not proof that a particular active socket uses one of them.',ta:'Linux sysctl, tc read-only ஆய்வும் Python 3-மும் பயன்படுத்தவும். கிடைக்கும் algorithms பட்டியல் ஒரு குறிப்பிட்ட active socket எதைப் பயன்படுத்துகிறது என்பதை நிரூபிக்காது.'},expected:{en:'Calculations return 500000 bytes, 20 ms, and 120 microseconds. Algorithm and queue names vary by kernel and host configuration.',ta:'கணக்குகள் 500000 bytes, 20 ms, 120 microseconds தரும். Algorithm, queue பெயர்கள் kernel, host அமைப்பைப் பொறுத்து மாறும்.'},cleanup:{en:'No sysctl values or queue disciplines are modified.',ta:'Sysctl மதிப்புகளோ queue disciplines-ஓ மாற்றப்படாது; cleanup இல்லை.'}},
    questions:[
      {question:{en:'What is the example bandwidth-delay product?',ta:'எடுத்துக்காட்டின் bandwidth-delay product என்ன?'},options:{en:['500000 bytes','5000 bytes','4 million bytes'],ta:['500000 bytes','5000 bytes','4 million bytes']},answer:0,explanation:{en:'Multiply 100 million bits/s by 0.04 s, then divide by eight.',ta:'100 million bits/s-ஐ 0.04 s-ஆல் பெருக்கி எட்டால் வகுக்கவும்.'}},
      {question:{en:'Which mechanism primarily spaces packet release?',ta:'முக்கியமாக packets வெளியிடும் இடைவெளியை அமைப்பது எது?'},options:{en:['Pacing','DNS negative caching','AS_PATH prepending'],ta:['Pacing','DNS negative caching','AS_PATH prepending']},answer:0,explanation:{en:'Pacing schedules release times; a congestion window bounds flight size.',ta:'Pacing வெளியிடும் நேரம் அமைக்கும்; congestion window flight size வரம்பிடும்.'}},
      {question:{en:'A tiny receive window caps a high-RTT flow. Does changing CUBIC to BBR alone solve it?',ta:'சிறிய receive window நீண்ட RTT flow-ஐ வரம்பிடுகிறது. CUBIC-ஐ BBR ஆக்கினால் மட்டும் தீருமா?'},options:{en:['No, flow control remains a separate bound','Yes, BBR ignores receiver limits','Yes, because RTT becomes zero'],ta:['இல்லை; flow control தனி வரம்பாகத் தொடரும்','ஆம்; BBR receiver வரம்பைப் புறக்கணிக்கும்','ஆம்; RTT பூஜ்யமாகும்']},answer:0,explanation:{en:'Congestion-control selection cannot authorize data beyond the advertised receiver capacity.',ta:'Receiver அறிவித்த capacity-க்கு அப்பால் அனுப்ப congestion-control தேர்வு அனுமதிக்காது.'}}
    ],refs:[['CUBIC congestion control','https://www.rfc-editor.org/rfc/rfc9438.html'],['BBR implementation and documentation','https://github.com/google/bbr'],['TCP congestion control principles','https://www.rfc-editor.org/rfc/rfc5681.html']]
  },
  {
    id:37,module:9,model:'routing',
    title:{en:'OSPF adjacency, flooding, and area boundaries',ta:'OSPF adjacency, flooding, area எல்லைகள்'},
    summary:{en:'Follow neighbor discovery through database synchronization and compute cost-based paths while recognizing why a healthy two-way neighbor need not become fully adjacent.',ta:'Neighbor discovery முதல் database synchronization வரை பின்தொடர்ந்து cost அடிப்படையில் பாதை கணக்கிடுவோம்; நல்ல two-way neighbor எல்லாமே full adjacency ஆக வேண்டியதில்லை என்பதையும் அறிந்துகொள்வோம்.'},
    prerequisites:{en:'IP forwarding, link-state routing, multicast addresses, and interface MTU.',ta:'IP forwarding, link-state routing, multicast addresses, interface MTU தெரிந்திருக்க வேண்டும்.'},
    objectives:{en:['Interpret neighbor states in their network-type context.','Separate flooding, SPF calculation, and forwarding installation.','Explain backbone areas, ABRs, and deliberate summarization.'],ta:['Network type-க்கு ஏற்ப neighbor states புரிந்துகொள்ளுதல்.','Flooding, SPF கணக்கு, forwarding installation பிரித்தறிதல்.','Backbone areas, ABRs, திட்டமிட்ட summarization விளக்குதல்.']},
    sections:[
      {heading:{en:'Discovery does not imply full adjacency',ta:'Discovery மட்டும் full adjacency அல்ல'},body:{en:'OSPF Hello exchanges discover neighbors and confirm bidirectional communication when each router sees its own identifier in the peer’s Hello. Parameters such as area, timers, authentication, and relevant options must agree. On a broadcast network, routers elect a designated router and backup to reduce the number of full adjacencies. Two DROther routers can remain in 2-Way normally. Point-to-point networks have different adjacency expectations, so state labels must be interpreted with network type and role.',ta:'OSPF Hello மூலம் neighbors கண்டறியப்படுகின்றன; peer Hello-வில் தன் identifier தெரிந்தால் இருதிசைத் தொடர்பு உறுதியாகிறது. Area, timers, authentication, தேவையான options பொருந்த வேண்டும். Broadcast network-ல் full adjacencies குறைய designated router, backup தேர்ந்தெடுக்கப்படுகின்றன. இரண்டு DROther routers இயல்பாக 2-Way-ல் இருக்கலாம். Point-to-point network-ல் எதிர்பார்ப்பு வேறு; state பெயரை network type, role உடன் புரிந்துகொள்ள வேண்டும்.'}},
      {heading:{en:'Synchronize before computing useful paths',ta:'பயனுள்ள பாதைக் கணக்குக்கு முன் synchronization'},body:{en:'Adjacency progresses through ExStart, Exchange, Loading, and Full as needed. Database Description packets summarize link-state contents; requests and updates obtain missing or newer LSAs, with acknowledgements supporting reliable flooding. Sequence numbers and aging help distinguish current information. SPF computes paths from the resulting database rather than directly from Hello packets. A synchronized database is still different from a forwarding entry: route selection, next-hop resolution, and installation must also succeed before application traffic can use the path.',ta:'தேவைக்கேற்ப adjacency ExStart, Exchange, Loading, Full வழியாக முன்னேறும். Database Description packets link-state உள்ளடக்கத்தைச் சுருக்குகின்றன; requests, updates மூலம் missing அல்லது புதிய LSAs கிடைக்கும்; acknowledgements நம்பகமான flooding உதவும். Sequence numbers, aging நடப்புத் தகவலைப் பிரித்தறிய உதவும். Hello-விலிருந்து நேரடியாக அல்லாமல் database-லிருந்து SPF பாதை கணக்கிடும். Database ஒத்திசைந்தாலும் forwarding entry வேறு; route தேர்வு, next-hop resolution, installation வெற்றியடைந்தால்தான் application traffic பாதையைப் பயன்படுத்தும்.'}},
      {heading:{en:'Areas limit topology scope',ta:'Areas topology பரவலை வரம்பிடும்'},body:{en:'Within an area, routers share detailed link-state topology. Area border routers connect areas and can advertise summarized reachability according to configuration and protocol rules. Backbone area 0 provides the inter-area structure; arbitrary disconnected area designs do not automatically work. Costs are additive and directional, and reference-bandwidth settings are implementation choices that should be consistent. OSPFv3 adapts the protocol for IPv6 and has different packet and addressing details, so OSPFv2 packet assumptions should not be copied blindly.',ta:'ஒரு area-க்குள் routers விரிவான link-state topology பகிர்கின்றன. Area border routers areas இணைத்து அமைப்பு, protocol விதிகளின்படி summarized reachability அறிவிக்கலாம். Backbone area 0 inter-area கட்டமைப்பை வழங்கும்; துண்டிக்கப்பட்ட areas தானாக இயங்காது. Costs கூட்டப்படுகின்றன; திசைக்கேற்ப மாறலாம். Reference-bandwidth implementation தேர்வு; ஒற்றுமையாக அமைக்க வேண்டும். OSPFv3 IPv6-க்குத் தழுவியதால் packet, addressing விவரங்கள் வேறு; OSPFv2 ஊகங்களை அப்படியே பயன்படுத்தக்கூடாது.'}}
    ],
    example:{en:'Router A reaches C directly with cost 30, or through B with A→B cost 10 and B→C cost 5. The two-hop path costs 15 and wins over the direct link. This is a cost decision, not a hop-count decision. If B→A has cost 40, the reverse computation can differ. On a shared LAN containing a DR, BDR, and two DROthers, a 2-Way relationship between the DROthers is expected rather than proof of failed synchronization.',ta:'A-விலிருந்து C நேரடிப் பாதை cost 30; B வழியாக A→B cost 10, B→C cost 5. இரண்டு-hop பாதையின் மொத்தம் 15 என்பதால் அது வெல்லும். இது hop எண்ணிக்கை அல்ல cost முடிவு. B→A cost 40 என்றால் reverse கணக்கு மாறலாம். DR, BDR, இரண்டு DROthers உள்ள LAN-ல் DROthers இடையிலான 2-Way இயல்பு; synchronization கோளாறு என்பதற்குச் சான்றல்ல.'},
    failure:{en:'Neighbors repeatedly enter ExStart or Exchange but do not reach Full. Compare Database Description MTU values, router IDs, network types, and authentication before changing timers. An MTU mismatch can reject database exchange even though small Hellos succeed. Ignoring the check without fixing the real packet-size path can hide a later forwarding failure.',ta:'Neighbors ExStart அல்லது Exchange-க்கு மீண்டும் மீண்டும் சென்று Full அடையவில்லை. Timers மாற்றும்முன் Database Description MTU, router IDs, network types, authentication ஒப்பிடவும். சிறிய Hellos சென்றாலும் MTU mismatch database exchange-ஐத் தடுக்கலாம். உண்மையான packet-size சிக்கலைச் சரிசெய்யாமல் check புறக்கணித்தால் பின்னர் forwarding கோளாறு மறைந்திருக்கலாம்.'},
    lab:{commands:"python3 - <<'PY'\nimport heapq\ng={'A':{'B':10,'C':30},'B':{'C':5},'C':{}}\nq=[(0,'A')]; best={}\nwhile q:\n    cost,node=heapq.heappop(q)\n    if node in best: continue\n    best[node]=cost\n    for peer,weight in g[node].items():\n        heapq.heappush(q,(cost+weight,peer))\nprint(best)\nPY",guidance:{en:'This isolated Python 3 exercise models directed shortest-path costs, not OSPF adjacency or LSA processing. Predict A, B, and C costs first.',ta:'தனித்த Python 3 பயிற்சி directed shortest-path cost மட்டும் காட்டும்; OSPF adjacency, LSA processing அல்ல. முதலில் A, B, C costs கணிக்கவும்.'},expected:{en:'The cost map is A:0, B:10, C:15. A higher-cost direct edge does not win merely because it is one hop.',ta:'Cost map A:0, B:10, C:15 வரும். ஒரே hop என்பதால் மட்டும் அதிக-cost நேரடி edge வெல்லாது.'},cleanup:{en:'No routing daemon, multicast socket, or network configuration is created.',ta:'Routing daemon, multicast socket, network configuration எதுவும் உருவாக்கப்படாது.'}},
    questions:[
      {question:{en:'Which example path wins from A to C?',ta:'எடுத்துக்காட்டில் A முதல் C வரை எது வெல்லும்?'},options:{en:['Via B with cost 15','Direct with cost 30','Whichever has fewer letters'],ta:['B வழியாக cost 15','நேரடியாக cost 30','குறைந்த எழுத்துள்ள பாதை']},answer:0,explanation:{en:'SPF compares summed eligible costs, not merely the number of links.',ta:'SPF தகுந்த costs-ன் கூட்டுத்தொகையை ஒப்பிடும்; link எண்ணிக்கையை மட்டும் அல்ல.'}},
      {question:{en:'Is 2-Way between two DROthers on a broadcast LAN necessarily a fault?',ta:'Broadcast LAN-ல் இரண்டு DROthers இடையில் 2-Way இருப்பது கட்டாயம் கோளாறா?'},options:{en:['No, it is normally expected','Yes, every neighbor pair must be Full','Yes, it means no Hello was received'],ta:['இல்லை; பொதுவாக எதிர்பார்க்கப்படுவது','ஆம்; எல்லா ஜோடியும் Full வேண்டும்','ஆம்; Hello வரவில்லை எனப் பொருள்']},answer:0,explanation:{en:'The DR/BDR design reduces full-adjacency count while retaining topology distribution.',ta:'DR/BDR வடிவம் topology பகிர்வைக் காத்து full adjacency எண்ணிக்கையைக் குறைக்கும்.'}},
      {question:{en:'Small Hellos work but database exchange stalls. What should be examined?',ta:'சிறிய Hellos இயங்கியும் database exchange நிற்கிறது. எதை ஆய்வது?'},options:{en:['Interface MTU and Database Description values','Only DNS search suffixes','HTTP cookie expiry'],ta:['Interface MTU, Database Description மதிப்புகள்','DNS search suffix மட்டும்','HTTP cookie expiry']},answer:0,explanation:{en:'Database exchange validates MTU-related information that a small Hello success does not establish.',ta:'சிறிய Hello வெற்றி உறுதிப்படுத்தாத MTU தகவலை database exchange சரிபார்க்கிறது.'}}
    ],refs:[['OSPFv2','https://www.rfc-editor.org/rfc/rfc2328.html'],['OSPF for IPv6','https://www.rfc-editor.org/rfc/rfc5340.html']]
  },
  {
    id:38,module:9,model:'bgp',
    title:{en:'BGP attributes, export filters, and RPKI origin checks',ta:'BGP attributes, export filters, RPKI origin சோதனைகள்'},
    summary:{en:'Apply policy before path preference, evaluate a route-origin authorization, and explain why an established BGP session is not evidence that every received route is safe to propagate.',ta:'Path preference-க்கு முன் policy பயன்படுத்தி route-origin authorization மதிப்பிடுவோம்; BGP session established என்பது எல்லா routes-ஐயும் பாதுகாப்பாகப் பரப்பலாம் என்பதல்ல என்பதை விளக்குவோம்.'},
    prerequisites:{en:'AS numbers, prefixes, longest-prefix forwarding, and internal versus external BGP.',ta:'AS numbers, prefixes, longest-prefix forwarding, internal/external BGP தெரிந்திருக்க வேண்டும்.'},
    objectives:{en:['Compare local preference, AS_PATH, MED, and next-hop reachability.','Design relationship-aware import and export checks.','Classify Valid, Invalid, and NotFound without overstating RPKI protection.'],ta:['Local preference, AS_PATH, MED, next-hop reachability ஒப்பிடுதல்.','உறவுக்கேற்ப import, export சோதனைகள் வடிவமைத்தல்.','RPKI பாதுகாப்பை மிகைப்படுத்தாமல் Valid, Invalid, NotFound வகைப்படுத்துதல்.']},
    sections:[
      {heading:{en:'Eligibility comes before preference',ta:'Preference-க்கு முன் eligibility'},body:{en:'An accepted BGP route carries path attributes and a next hop that must be usable in the routing context. Local preference expresses an AS-wide preference for exit paths; larger values are normally preferred. AS_PATH supports loop detection and contributes to selection, but a shorter path does not override every policy attribute. MED can express preferred entry among relevant paths, with comparison rules that need care. Vendor extensions and configurable tie-breakers mean a single universal best-path mnemonic is insufficient.',ta:'ஏற்கப்பட்ட BGP route-ல் path attributes, routing context-ல் பயன்படுத்தக்கூடிய next hop வேண்டும். Local preference AS முழுவதற்கான வெளியேறும் பாதை விருப்பத்தைச் சொல்கிறது; பொதுவாக பெரிய மதிப்பு முன்னுரிமை பெறும். AS_PATH loop கண்டறியவும் தேர்வுக்கும் உதவும்; குறுகிய path எல்லா policy attributes-ஐயும் மீறாது. MED பொருத்தமான paths-க்கிடையில் நுழைவு விருப்பம் காட்டும்; comparison விதிகளை கவனிக்க வேண்டும். Vendor extensions, அமைக்கக்கூடிய tie-breakers இருப்பதால் ஒரே best-path நினைவுச் சூத்திரம் போதாது.'}},
      {heading:{en:'Export only what the relationship permits',ta:'உறவு அனுமதிப்பதை மட்டும் export செய்யவும்'},body:{en:'Import filters constrain which prefixes and origins a neighbor may advertise. Export filters prevent customer, peer, and transit relationships from accidentally turning into unintended transit. Prefix-length limits, explicit authorized sets, community handling, and maximum-prefix protection address different problems. A session reaching Established proves only that the BGP transport and state machine progressed. Apply a default-reject policy where appropriate and test intended announcements before activation. A leaked legitimate prefix can be operationally harmful even when its origin is cryptographically authorized.',ta:'Import filters neighbor அறிவிக்கக்கூடிய prefixes, origins வரம்பிடும். Export filters customer, peer, transit உறவுகள் தவறுதலாக வேண்டாத transit ஆகாமல் தடுக்கும். Prefix-length வரம்பு, அனுமதிக்கப்பட்ட பட்டியல், community கையாளுதல், maximum-prefix பாதுகாப்பு வெவ்வேறு பணிகள். Established session என்பது transport, state machine முன்னேறியதையே நிரூபிக்கும். பொருத்தமான இடத்தில் default-reject அமைத்து செயல்படுத்தும்முன் திட்டமிட்ட அறிவிப்புகளைச் சோதிக்க வேண்டும். Origin அனுமதி சரியாக இருந்தாலும் legitimate prefix leak தீங்கு தரலாம்.'}},
      {heading:{en:'Origin validation answers a narrow question',ta:'Origin validation ஒரு குறிப்பிட்ட கேள்விக்கான பதில்'},body:{en:'RPKI validators produce validated prefix-origin data from signed authorizations. A route is Valid if at least one covering authorization matches its origin AS and permits its prefix length. It is Invalid when covering data exists but no entry authorizes that combination, and NotFound when no covering data exists. Validation state is input to local routing policy, not an automatic universal decision. Origin validation does not verify the entire AS_PATH, business relationship, or forwarding behavior, and cache freshness and validator availability need monitoring.',ta:'RPKI validators கையொப்ப authorization-லிருந்து சரிபார்க்கப்பட்ட prefix-origin தகவல் தருகின்றன. குறைந்தது ஒரு covering authorization origin AS, prefix நீளம் இரண்டையும் அனுமதித்தால் Valid. Covering தகவல் இருந்தும் அந்தச் சேர்க்கையை எந்தப் பதிவும் அனுமதிக்காவிட்டால் Invalid; covering தகவலே இல்லையெனில் NotFound. இந்நிலை local routing policy-க்கு உள்ளீடு; தானியக்கப் பொதுமுடிவு அல்ல. முழு AS_PATH, வணிக உறவு, forwarding நடத்தை சரிபார்க்காது; cache freshness, validator கிடைப்பையும் கண்காணிக்க வேண்டும்.'}}
    ],
    example:{en:'A teaching authorization covers 203.0.113.0/24 for AS 64496 with maximum length /24. An announcement of that /24 by AS 64496 is Valid. Announcing 203.0.113.0/25 from the same AS is Invalid because it exceeds maxLength; announcing the /24 from AS 64497 is also Invalid. A separate 192.0.2.0/24 with no covering authorization is NotFound. If two eligible paths have local preferences 200 and 100, policy can prefer 200 despite a longer AS_PATH.',ta:'பயிற்சி authorization 203.0.113.0/24-ஐ AS 64496-க்கு maxLength /24 உடன் அனுமதிக்கிறது. அதே AS-ன் /24 அறிவிப்பு Valid. அதே AS /25 அறிவித்தால் maxLength மீறுவதால் Invalid; AS 64497 /24 அறிவித்தாலும் Invalid. Covering authorization இல்லாத 192.0.2.0/24 NotFound. தகுந்த இரண்டு paths-ன் local preference 200, 100 என்றால் நீளமான AS_PATH இருந்தாலும் 200-ஐ policy தேரலாம்.'},
    failure:{en:'A provider accepts a customer’s default route and exports it widely. RPKI alone may not reject every damaging leak, particularly when the origin is legitimate. Compare the actual received and advertised prefix sets with the customer contract; test both positive permission and negative export cases before changing a live route map.',ta:'Provider customer-ன் default route ஏற்று பரவலாக export செய்கிறது. Origin சரியாக இருக்கும்போது தீங்கான எல்லா leak-களையும் RPKI மட்டும் தடுக்காது. உண்மையில் பெற்ற, அனுப்பிய prefix பட்டியலை customer ஒப்பந்தத்துடன் ஒப்பிட வேண்டும்; live route map மாற்றும்முன் அனுமதி மற்றும் தடைச் சோதனைகள் இரண்டும் தேவை.'},
    lab:{commands:"python3 - <<'PY'\nfrom ipaddress import ip_network\ncover=ip_network('203.0.113.0/24')\nfor prefix,asn in [('203.0.113.0/24',64496),('203.0.113.0/25',64496),('203.0.113.0/24',64497),('192.0.2.0/24',64496)]:\n    n=ip_network(prefix)\n    state='NotFound' if not n.subnet_of(cover) else ('Valid' if asn==64496 and n.prefixlen<=24 else 'Invalid')\n    print(prefix,asn,state)\nPY",guidance:{en:'The local Python 3 model uses one already-validated teaching authorization. It does not fetch RPKI objects, verify signatures, or implement multi-entry validation.',ta:'உள்ளூர் Python 3 model ஏற்கெனவே சரிபார்க்கப்பட்டதாகக் கருதும் ஒரு பயிற்சி authorization பயன்படுத்துகிறது. RPKI objects பெறுதல், signatures சரிபார்த்தல், பல-entry validation இதில் இல்லை.'},expected:{en:'The four states are Valid, Invalid, Invalid, and NotFound in that order. No BGP messages leave the machine.',ta:'வரிசையாக Valid, Invalid, Invalid, NotFound வரும். கணினியிலிருந்து BGP messages வெளியே செல்லாது.'},cleanup:{en:'No sessions, route maps, or authorization objects are created.',ta:'Sessions, route maps, authorization objects உருவாக்கப்படாது; cleanup தேவையில்லை.'}},
    questions:[
      {question:{en:'Why is the example /25 from AS 64496 Invalid?',ta:'AS 64496-ன் எடுத்துக்காட்டு /25 ஏன் Invalid?'},options:{en:['It exceeds authorized maximum length /24','All /25 routes are forbidden globally','Its address has too many decimal digits'],ta:['அனுமதித்த அதிகபட்ச நீளம் /24-ஐ மீறுகிறது','உலகளவில் எல்லா /25 routes-மும் தடை','Address-ல் அதிக decimal இலக்கங்கள் உள்ளன']},answer:0,explanation:{en:'The covering authorization permits the AS but not that more-specific prefix length.',ta:'Covering authorization AS-ஐ அனுமதிக்கிறது; அந்தக் கூடுதல் specific நீளத்தை அனுமதிக்கவில்லை.'}},
      {question:{en:'What does NotFound mean here?',ta:'இங்கே NotFound என்ன பொருள்?'},options:{en:['No covering validated authorization exists','The route is proven malicious','The complete AS path was verified'],ta:['Covering validated authorization இல்லை','Route தீங்கானது என்று நிரூபிக்கப்பட்டது','முழு AS path சரிபார்க்கப்பட்டது']},answer:0,explanation:{en:'Absence of covering data is different from an authorization mismatch.',ta:'Covering தகவல் இல்லாததும் authorization பொருந்தாததும் வேறுபட்டவை.'}},
      {question:{en:'Which control directly limits accidental transit exports?',ta:'தற்செயலான transit exports-ஐ நேரடியாக வரம்பிடுவது எது?'},options:{en:['Relationship-aware export filtering','A longer HTTP timeout','Only a successful BGP handshake'],ta:['உறவுக்கேற்ற export filtering','நீளமான HTTP timeout','வெற்றியான BGP handshake மட்டும்']},answer:0,explanation:{en:'Export policy constrains what is propagated; a session and origin validity alone do not express transit permission.',ta:'Export policy பரப்பப்படும் routes வரம்பிடும்; session, origin validity மட்டும் transit அனுமதியைச் சொல்லாது.'}}
    ],refs:[['BGP-4','https://www.rfc-editor.org/rfc/rfc4271.html'],['BGP operations and security','https://www.rfc-editor.org/rfc/rfc7454.html'],['RPKI origin validation','https://www.rfc-editor.org/rfc/rfc6811.html'],['Origin validation clarifications','https://www.rfc-editor.org/rfc/rfc8481.html']]
  },
  {
    id:39,module:9,model:'routing',
    title:{en:'Multicast membership, IGMP, MLD, and PIM',ta:'Multicast membership மற்றும் IGMP, MLD, PIM பணிகள்'},
    summary:{en:'Separate receiver membership from multicast routing, follow source-specific joins, and diagnose reverse-path failures that ordinary unicast tests can miss.',ta:'Receiver membership-ஐ multicast routing-லிருந்து பிரித்து, source-specific joins பின்தொடர்ந்து, சாதாரண unicast சோதனையில் தெரியாத reverse-path கோளாறுகளைக் கண்டறிவோம்.'},
    prerequisites:{en:'Unicast routing, IPv4 and IPv6 multicast, and Ethernet switching.',ta:'Unicast routing, IPv4/IPv6 multicast, Ethernet switching தெரிந்திருக்க வேண்டும்.'},
    objectives:{en:['Distinguish IGMP/MLD, switch snooping, and PIM roles.','Interpret (*,G) and (S,G) state.','Use RPF reasoning and bandwidth calculations to locate delivery failures.'],ta:['IGMP/MLD, switch snooping, PIM பணிகளை வேறுபடுத்துதல்.','(*,G), (S,G) state பொருள் அறிதல்.','RPF சிந்தனை, bandwidth கணக்கு மூலம் delivery கோளாறு கண்டறிதல்.']},
    sections:[
      {heading:{en:'Membership is local receiver interest',ta:'Membership என்பது உள்ளூர் receiver விருப்பம்'},body:{en:'IGMP communicates IPv4 receiver membership to neighboring multicast routers; MLD serves IPv6 using ICMPv6 messages. Source-filtering versions can express interest in traffic from selected sources. A sender does not have to join a group merely to transmit to it. Switch snooping observes membership signaling to constrain layer-two replication, but it is not a substitute for multicast routing. Querier behavior and membership timers matter: stale or absent state can either flood traffic unnecessarily or stop legitimate delivery.',ta:'IGMP IPv4 receiver membership-ஐ அருகிலுள்ள multicast routers-க்கு தெரிவிக்கிறது; IPv6-க்கு MLD, ICMPv6 messages பயன்படுத்துகிறது. Source-filtering versions குறிப்பிட்ட sources-ன் traffic விருப்பத்தைச் சொல்லும். Group-க்கு அனுப்ப sender கட்டாயம் join செய்ய வேண்டியதில்லை. Switch snooping membership signaling பார்த்து layer-two replication குறைக்கும்; அது multicast routing-க்கு மாற்றல்ல. Querier நடத்தை, membership timers முக்கியம்; பழைய அல்லது இல்லாத state தேவையற்ற flooding அல்லது சரியான delivery நிறுத்தம் ஏற்படுத்தலாம்.'}},
      {heading:{en:'Routers construct distribution trees',ta:'Routers distribution trees அமைக்கின்றன'},body:{en:'PIM sparse mode builds shared trees rooted at a rendezvous point for any-source groups and can move receivers toward source-specific shortest-path trees. The notation (*,G) means group state independent of a particular source; (S,G) identifies a source and group. Source-specific multicast uses explicit source interest and does not need the ordinary shared-tree rendezvous process for that traffic. Multicast availability depends on deployment and administrative policy; choosing a group address does not create global Internet distribution.',ta:'PIM sparse mode any-source groups-க்கு rendezvous point-ஐ வேர் கொண்ட shared trees அமைத்து receivers-ஐ source-specific shortest-path tree-க்கு மாற்றலாம். (*,G) என்பது குறிப்பிட்ட source சாராத group state; (S,G) source, group ஜோடி. Source-specific multicast வெளிப்படையான source விருப்பத்தைப் பயன்படுத்துவதால் அந்த traffic-க்கு வழக்கமான shared-tree rendezvous தேவையில்லை. Multicast கிடைப்பது deployment, நிர்வாக policy சார்ந்தது; group address தேர்ந்தெடுத்தாலே உலக Internet விநியோகம் உருவாகாது.'}},
      {heading:{en:'Reverse-path checks stop loops',ta:'Reverse-path checks loops தடுக்கின்றன'},body:{en:'A multicast router checks whether a packet arrived on the expected upstream interface according to its reverse-path information. Packets arriving on an unexpected interface can be dropped even when a receiver can ping the source. The relevant multicast routing information may differ from the ordinary unicast table. Investigate incoming interface, outgoing interface list, source address, group scope, hop limit, and policy together. Capture at successive authorized points to distinguish absent joins from RPF rejection or a downstream application that never opened its receive socket.',ta:'Multicast router packet எதிர்பார்க்கப்பட்ட upstream interface-ல் வந்ததா என்று reverse-path தகவலால் பார்க்கிறது. Receiver source-ஐ ping செய்ய முடிந்தாலும் தவறான interface-ல் வந்த multicast drop ஆகலாம். Multicast routing தகவல் சாதாரண unicast table-இலிருந்து வேறாக இருக்கலாம். Incoming interface, outgoing interface பட்டியல், source, group scope, hop limit, policy அனைத்தையும் சேர்த்து ஆய்வு செய்யவும். அனுமதியுள்ள அடுத்தடுத்த இடங்களில் capture செய்து missing join, RPF rejection, receive socket திறக்காத application ஆகியவற்றைப் பிரிக்கலாம்.'}}
    ],
    example:{en:'A source sends an 8 Mbit/s stream to three receivers behind one branch router. The shared upstream link needs approximately one 8 Mbit/s copy, while three separate downstream links each carry a copy, totaling 24 Mbit/s across those links before overhead. For source-specific traffic, receiver interest is in a pair such as source 192.0.2.10 and group 232.1.1.1. Two sources using the same group still create distinct (S,G) state.',ta:'ஒரு source branch router பின்னுள்ள மூன்று receivers-க்கு 8 Mbit/s stream அனுப்புகிறது. பகிரப்பட்ட upstream-ல் சுமார் ஒரு 8 Mbit/s copy போதும்; மூன்று தனி downstream links தலா ஒரு copy எடுத்தால் overhead-க்கு முன் மொத்தம் 24 Mbit/s. Source-specific traffic-ல் receiver 192.0.2.10 source, 232.1.1.1 group ஜோடியில் விருப்பம் தெரிவிக்கும். ஒரே group பயன்படுத்தும் இரண்டு sources-க்கும் தனித்தனி (S,G) state இருக்கும்.'},
    failure:{en:'Video disappears after a routing change, yet unicast ping still succeeds. A new multicast ingress may fail the router’s RPF check because the expected source-facing interface did not change consistently. Compare multicast route state and join propagation; repeatedly restarting the receiver will not repair an upstream reverse-path inconsistency.',ta:'Routing மாற்றத்துக்குப் பிறகு video மறைந்தாலும் unicast ping இயங்குகிறது. எதிர்பார்த்த source-facing interface ஒத்திசைந்து மாறாததால் புதிய multicast ingress RPF check-ல் தோற்கலாம். Multicast route state, join பரவலை ஒப்பிடவும்; receiver-ஐ மீண்டும் தொடங்கிக்கொண்டே இருப்பது upstream reverse-path முரண்பாட்டைச் சரிசெய்யாது.'},
    lab:{commands:"ip maddr show\ncat /proc/net/igmp\ncat /proc/net/igmp6\npython3 - <<'PY'\nrate=8\nreceivers=3\nprint('shared_upstream_Mbps',rate)\nprint('sum_downstream_Mbps',rate*receivers)\nPY",guidance:{en:'On Linux inspect local memberships without joining a group. Kernel tables are host membership evidence, not proof that upstream PIM state exists.',ta:'Linux-ல் group join செய்யாமல் உள்ளூர் memberships பார்க்கவும். Kernel பட்டியல் host membership சான்று மட்டுமே; upstream PIM state இருப்பதை நிரூபிக்காது.'},expected:{en:'Link-local control memberships may appear even without a video application. The arithmetic prints 8 and 24 Mbit/s.',ta:'Video application இல்லாவிட்டாலும் link-local control memberships இருக்கலாம். கணக்கில் 8, 24 Mbit/s வரும்.'},cleanup:{en:'No sockets, memberships, queriers, or router configuration are created.',ta:'Sockets, memberships, queriers, router configuration எதுவும் உருவாக்கப்படாது.'}},
    questions:[
      {question:{en:'What upstream rate is needed for the shared part of the example tree?',ta:'எடுத்துக்காட்டு tree-ன் shared upstream-க்கு எந்த rate தேவை?'},options:{en:['About 8 Mbit/s before overhead','24 Mbit/s on every shared link','Zero because multicast has no packets'],ta:['Overhead முன் சுமார் 8 Mbit/s','ஒவ்வொரு shared link-லும் 24 Mbit/s','Multicast-ல் packets இல்லாததால் பூஜ்யம்']},answer:0,explanation:{en:'Replication happens at the branching point, so the upstream need not carry three separate copies.',ta:'Branch இடத்தில் replication நடப்பதால் upstream மூன்று தனி copies எடுத்துச் செல்ல வேண்டியதில்லை.'}},
      {question:{en:'Which mechanism reports IPv6 listener membership?',ta:'IPv6 listener membership தெரிவிப்பது எது?'},options:{en:['MLD','ARP','TCP SACK'],ta:['MLD','ARP','TCP SACK']},answer:0,explanation:{en:'MLD uses ICMPv6; IGMP is the corresponding IPv4 family of membership protocols.',ta:'MLD ICMPv6 பயன்படுத்தும்; IPv4 membership protocol குடும்பம் IGMP.'}},
      {question:{en:'Ping works but multicast enters the wrong upstream interface. What can drop it?',ta:'Ping இயங்கியும் multicast தவறான upstream interface-ல் வந்தால் எது drop செய்யலாம்?'},options:{en:['RPF checking','DNS TTL expiry alone','A TCP receive window'],ta:['RPF checking','DNS TTL expiry மட்டும்','TCP receive window']},answer:0,explanation:{en:'Multicast loop prevention validates the ingress against reverse-path state.',ta:'Multicast loop தடுப்பு ingress-ஐ reverse-path state உடன் சரிபார்க்கும்.'}}
    ],refs:[['IGMPv3','https://www.rfc-editor.org/rfc/rfc3376.html'],['MLDv2','https://www.rfc-editor.org/rfc/rfc3810.html'],['PIM sparse mode','https://www.rfc-editor.org/rfc/rfc7761.html'],['Source-specific multicast','https://www.rfc-editor.org/rfc/rfc4607.html']]
  },
  {
    id:40,module:9,model:'routing',
    title:{en:'MPLS labels, VRFs, and provider VPN routes',ta:'MPLS labels, VRFs மற்றும் provider VPN வழித்தடங்கள்'},
    summary:{en:'Follow a two-label packet through a provider network and distinguish forwarding isolation, unique route naming, and route-import policy from cryptographic protection.',ta:'Provider network வழியாக இரண்டு-label packet-ஐப் பின்தொடர்ந்து forwarding isolation, தனித்த route பெயர், route-import policy ஆகியவற்றை cryptographic பாதுகாப்பிலிருந்து வேறுபடுத்துவோம்.'},
    prerequisites:{en:'IP forwarding, BGP reachability, routing tables, and encapsulation.',ta:'IP forwarding, BGP reachability, routing tables, encapsulation தெரிந்திருக்க வேண்டும்.'},
    objectives:{en:['Explain push, swap, and pop with locally significant labels.','Separate VRF, route distinguisher, and route target functions.','Diagnose missing VPN reachability without assuming labels encrypt payloads.'],ta:['உள்ளூர் பொருளுள்ள labels-ன் push, swap, pop விளக்குதல்.','VRF, route distinguisher, route target பணிகளைப் பிரித்தல்.','Labels payload encrypt செய்கின்றன எனக் கருதாமல் VPN reachability கோளாறு கண்டறிதல்.']},
    sections:[
      {heading:{en:'A label selects forwarding behavior',ta:'Label forwarding நடத்தையைத் தேர்கிறது'},body:{en:'An MPLS label-stack entry occupies four bytes and contains a 20-bit label, traffic-class bits, a bottom-of-stack bit, and TTL. Labels generally have local significance: receiving label 100 on one router does not mean label 100 has the same meaning everywhere. An ingress can push labels, transit routers can swap the top label, and an egress or penultimate hop can pop labels. MPLS forwarding uses installed label state rather than interpreting each application’s payload.',ta:'MPLS label-stack entry நான்கு bytes; அதில் 20-bit label, traffic-class bits, bottom-of-stack bit, TTL உள்ளன. Labels பொதுவாக உள்ளூரில் பொருள்படும்; ஒரு router-ன் label 100 எல்லா இடங்களிலும் அதே பொருள் அல்ல. Ingress labels push செய்யும்; transit top label swap செய்யும்; egress அல்லது முந்தைய hop labels pop செய்யலாம். MPLS ஒவ்வொரு application payload-ஐப் புரிந்துகொள்ளாமல் நிறுவப்பட்ட label state மூலம் forward செய்கிறது.'}},
      {heading:{en:'VRFs permit overlapping customer addresses',ta:'VRFs ஒரே addresses-ஐ வாடிக்கையாளர்கள் பயன்படுத்த உதவும்'},body:{en:'A VRF supplies a separate routing and forwarding context, often selected by the customer-facing interface. Two customers can both use 10.0.0.0/24 without sharing the same destination table. In a BGP/MPLS layer-three VPN, a route distinguisher makes otherwise identical customer prefixes distinct in VPN route exchange. Route targets are extended-community policy markers controlling import and export. An RD is not a security policy, and matching RDs are not the rule for deciding which VRFs exchange routes.',ta:'VRF தனி routing, forwarding context தருகிறது; customer-facing interface இதைத் தேரலாம். இரண்டு customers 10.0.0.0/24 பயன்படுத்தியும் ஒரே destination table பகிர வேண்டியதில்லை. BGP/MPLS layer-three VPN-ல் route distinguisher ஒரே customer prefixes-ஐ VPN exchange-ல் தனித்தனியாக்கும். Route targets என்பது import, export கட்டுப்படுத்தும் extended-community policy குறிகள். RD security policy அல்ல; RD ஒன்று என்பதாலேயே VRFs routes பகிர்வதில்லை.'}},
      {heading:{en:'Transport and service labels solve separate lookups',ta:'Transport, service labels தனித்த lookup பணிகள்'},body:{en:'A common VPN packet has an outer transport label that reaches the remote provider edge and an inner VPN label that selects the service forwarding context there. The provider core can forward without learning every customer route, although the transport still needs a working control plane and underlay. Penultimate-hop popping may remove the outer label before the final router. Isolation depends on correct interface association, control-plane policy, and label handling; payload confidentiality requires a separate cryptographic mechanism when the threat model demands it.',ta:'வழக்கமான VPN packet-ல் outer transport label remote provider edge-ஐ அடையவும் inner VPN label அங்கே service forwarding context தேரவும் உதவும். Provider core ஒவ்வொரு customer route-ஐயும் கற்காமல் forward செய்யலாம்; ஆனால் transport control plane, underlay இயங்க வேண்டும். Penultimate-hop popping இறுதி router-க்கு முன் outer label நீக்கலாம். Isolation சரியான interface இணைப்பு, control-plane policy, label கையாளுதலைச் சாரும்; தேவையான threat model-க்கு payload confidentiality தனி cryptographic முறையால் வழங்கப்பட வேண்டும்.'}}
    ],
    example:{en:'Customer Red and customer Blue both advertise 10.0.0.0/24. PE1 exports Red with RD 64496:1 and route target 64496:100; Blue uses RD 64496:2 and target 64496:200. A remote Red VRF imports target 64496:100 only. Its packet may carry transport label 16000 and VPN label 24000, adding eight bytes. The actual numeric labels are illustrative and assigned locally; the targets, rather than RD equality, express the intended sharing.',ta:'Red, Blue customers இருவரும் 10.0.0.0/24 அறிவிக்கின்றனர். PE1 Red-க்கு RD 64496:1, route target 64496:100; Blue-க்கு RD 64496:2, target 64496:200 தருகிறது. Remote Red VRF 64496:100 மட்டும் import செய்கிறது. Packet transport label 16000, VPN label 24000 எடுத்தால் எட்டு bytes கூடும். இவை உள்ளூரில் ஒதுக்கப்படும் விளக்க எண்கள்; பகிர்தலை RD ஒற்றுமை அல்ல route targets தெரிவிக்கின்றன.'},
    failure:{en:'A customer route appears in VPN BGP output but not in the destination VRF. Check import route targets and next-hop resolution before testing the customer application. Conversely, an overly broad import target can leak another tenant’s route even when all label-switched paths are healthy. Missing isolation is a policy failure, not a bandwidth problem.',ta:'Customer route VPN BGP-ல் இருந்தும் destination VRF-ல் இல்லை. Application சோதனைக்கு முன் import route targets, next-hop resolution பார்க்கவும். மிக விரிவான import target மற்ற tenant route-ஐ leak செய்யலாம்; label paths அனைத்தும் நல்லதாக இருந்தாலும் இது நடக்கும். Isolation குறைவு policy கோளாறு; bandwidth சிக்கல் அல்ல.'},
    lab:{commands:"python3 - <<'PY'\nroutes=[('64496:1','10.0.0.0/24',{'64496:100'}),('64496:2','10.0.0.0/24',{'64496:200'})]\nimports={'64496:100'}\nfor rd,prefix,targets in routes:\n    print(rd,prefix,'import' if targets & imports else 'skip')\nprint('two_label_overhead_bytes',2*4)\nPY\nip -d link show type vrf",guidance:{en:'Use Python 3 and Linux iproute2. The calculation models import membership only; the read-only VRF list may be empty and does not create MPLS state.',ta:'Python 3, Linux iproute2 பயன்படுத்தவும். கணக்கு import உறுப்புரிமையை மட்டும் காட்டும்; read-only VRF பட்டியல் காலியாக இருக்கலாம்; MPLS state உருவாகாது.'},expected:{en:'Red imports, Blue is skipped, and two labels add eight bytes. Real encapsulation may include additional labels and headers.',ta:'Red import, Blue skip, இரண்டு labels எட்டு bytes என்று வரும். உண்மையில் கூடுதல் labels, headers இருக்கலாம்.'},cleanup:{en:'No VRFs, interfaces, label entries, or BGP configuration are changed.',ta:'VRFs, interfaces, label entries, BGP configuration எதுவும் மாற்றப்படாது.'}},
    questions:[
      {question:{en:'What controls VPN route import in the example?',ta:'எடுத்துக்காட்டில் VPN route import கட்டுப்படுத்துவது எது?'},options:{en:['Route target matching','Identical RD values everywhere','TCP port 443'],ta:['Route target பொருத்தம்','எங்கும் ஒரே RD மதிப்புகள்','TCP port 443']},answer:0,explanation:{en:'Targets express import/export policy; RDs distinguish VPN route identities.',ta:'Targets import/export policy சொல்கின்றன; RDs VPN route identity வேறுபடுத்துகின்றன.'}},
      {question:{en:'How much space do three MPLS label entries occupy?',ta:'மூன்று MPLS label entries எவ்வளவு இடம் எடுக்கும்?'},options:{en:['12 bytes','60 bytes','3 bits'],ta:['12 bytes','60 bytes','3 bits']},answer:0,explanation:{en:'Each stack entry is four bytes, so three entries total twelve.',ta:'ஒவ்வொரு stack entry நான்கு bytes; மூன்று entries பன்னிரண்டு.'}},
      {question:{en:'Does a provider MPLS VPN automatically encrypt customer payload?',ta:'Provider MPLS VPN தானாக customer payload encrypt செய்யுமா?'},options:{en:['No, isolation and encryption are separate properties','Yes, every label is a cipher key','Only when the RD ends in 1'],ta:['இல்லை; isolation, encryption தனிப் பண்புகள்','ஆம்; ஒவ்வொரு label-மும் cipher key','RD 1-ல் முடிந்தால் மட்டும்']},answer:0,explanation:{en:'Label switching does not supply cryptographic payload confidentiality.',ta:'Label switching cryptographic payload confidentiality வழங்காது.'}}
    ],refs:[['MPLS architecture','https://www.rfc-editor.org/rfc/rfc3031.html'],['MPLS label stack encoding','https://www.rfc-editor.org/rfc/rfc3032.html'],['BGP/MPLS IP VPNs','https://www.rfc-editor.org/rfc/rfc4364.html']]
  },
  {
    id:41,module:10,model:'dns',
    title:{en:'DNS zones, delegation, DNSSEC, and DoH',ta:'DNS zones, delegation, DNSSEC, DoH ஆகியவற்றின் தொடர்பு'},
    summary:{en:'Follow authority across a zone cut, distinguish parent and child records, and separate DNS data authentication from encrypted transport to a recursive resolver.',ta:'Zone cut வழியாக authority மாறுவதைப் பின்தொடர்ந்து parent, child records வேறுபாட்டையும் DNS data authentication, recursive resolver-க்கு encrypted transport ஆகியவற்றின் வேறுபாட்டையும் அறிந்துகொள்வோம்.'},
    prerequisites:{en:'Recursive resolution, DNS record types, TTL, TLS, and public-key signatures.',ta:'Recursive resolution, DNS record types, TTL, TLS, public-key signatures தெரிந்திருக்க வேண்டும்.'},
    objectives:{en:['Identify zone cuts, glue, and authoritative answers.','Explain DS-to-DNSKEY validation and signed denial.','Diagnose DNSSEC failures separately from DoH connection failures.'],ta:['Zone cuts, glue, authoritative answers கண்டறிதல்.','DS முதல் DNSKEY validation, signed denial விளக்குதல்.','DNSSEC கோளாறையும் DoH connection கோளாறையும் பிரித்தறிதல்.']},
    sections:[
      {heading:{en:'A zone is an administrative slice of the tree',ta:'Zone என்பது பெயர் மரத்தின் நிர்வாகப் பகுதி'},body:{en:'A domain name identifies a position in the namespace; a zone contains authoritative data up to delegated cuts. A parent publishes NS records for a child delegation, while the child serves its own apex SOA and NS data. In-bailiwick name servers can require parent glue addresses to break a circular lookup dependency. Glue is bootstrap information rather than an authoritative answer for every use. Parent and child NS sets should be consistent, but they live in different administrative locations and can drift during changes.',ta:'Domain name namespace-ல் ஒரு இடத்தைக் குறிக்கும்; zone delegated cuts வரையிலான authoritative data கொண்டது. Parent child delegation-க்கு NS records வெளியிடும்; child தன் apex SOA, NS data வழங்கும். அதே child பகுதியிலுள்ள name servers-க்கு circular lookup தவிர்க்க parent glue addresses தேவைப்படலாம். Glue தொடக்க உதவித் தகவல்; எல்லாப் பயன்பாட்டுக்கும் authoritative பதில் அல்ல. Parent, child NS பட்டியல்கள் ஒத்திருக்க வேண்டும்; ஆனால் நிர்வாக இடங்கள் வேறு என்பதால் மாற்றத்தின் போது விலகலாம்.'}},
      {heading:{en:'DNSSEC validates data and absence',ta:'DNSSEC data மற்றும் இல்லாமையைச் சரிபார்க்கும்'},body:{en:'DNSSEC adds signatures over record sets, DNSKEY material, and a chain from a trust anchor through parent DS records. A validator checks signatures, validity periods, and the authenticated delegation relationship. NSEC or NSEC3 supports authenticated denial so an absent name or type is not merely an unsigned assertion. A signed zone with a broken chain can be bogus, whereas a deliberately unsigned delegation can be insecure without being bogus. TTL caching and signature expiry are separate clocks that both matter during key rollover.',ta:'DNSSEC record sets மீது signatures, DNSKEY material, trust anchor-லிருந்து parent DS வழியான chain சேர்க்கிறது. Validator signatures, validity காலம், authenticated delegation உறவு சரிபார்க்கும். NSEC அல்லது NSEC3 மூலம் name அல்லது type இல்லை என்பதற்கும் authenticated denial கிடைக்கும். உடைந்த chain கொண்ட signed zone bogus ஆகலாம்; திட்டமிட்ட unsigned delegation insecure என்றாலும் bogus அவசியமில்லை. TTL cache நேரமும் signature expiry நேரமும் வேறு; key rollover-ல் இரண்டும் முக்கியம்.'}},
      {heading:{en:'DoH secures a transport relationship',ta:'DoH ஒரு transport உறவைப் பாதுகாக்கிறது'},body:{en:'DNS over HTTPS carries DNS messages over HTTPS between a client and a resolver. It protects that channel against ordinary passive observation and modification, but the resolver still sees the queries it processes. DoH does not itself make unsigned authoritative data signed, and a DNSSEC-valid answer need not have traveled over DoH. Resolver selection, bootstrap resolution, caching, and organizational policy still affect results. Compare the same query type through known resolver paths rather than assuming every browser and operating system shares one cache.',ta:'DNS over HTTPS client, resolver இடையே DNS messages-ஐ HTTPS மூலம் எடுத்துச் செல்லும். அந்த channel-ல் சாதாரண ஒட்டுக்கேட்பு, மாற்றம் தடுக்கப்படும்; ஆனால் resolver தானே process செய்யும் queries பார்க்கும். DoH unsigned authoritative data-க்கு signature உருவாக்காது; DNSSEC-valid பதில் கட்டாயம் DoH வழியே வந்திருக்க வேண்டியதில்லை. Resolver தேர்வு, bootstrap resolution, caching, நிறுவன policy முடிவை மாற்றும். Browser, OS ஒரே cache பகிர்கின்றன எனக் கருதாமல் ஒரே query type-ஐ தெரிந்த resolver பாதைகளில் ஒப்பிட வேண்டும்.'}}
    ],
    example:{en:'Imagine parent example.test delegates lab.example.test to ns1.lab.example.test. Without an address hint, resolving that server requires entering the very zone whose server is unknown, so the parent supplies glue. If the parent also publishes a DS digest matching the child’s signing key, a validator can extend its trust chain. A valid signature does not conceal the queried name; using DoH to the chosen recursive resolver protects a different part of the exchange.',ta:'Parent example.test, lab.example.test-ஐ ns1.lab.example.test-க்கு delegate செய்கிறது எனக் கொள்வோம். Address உதவி இல்லாமல் அந்த server-ஐத் தீர்க்க server தெரியாத அதே zone-க்குள் செல்ல வேண்டும்; அதனால் parent glue தரும். Parent child signing key-க்கு பொருந்தும் DS digest வெளியிட்டால் validator trust chain நீட்டிக்கும். செல்லுபடியான signature query name-ஐ மறைக்காது; தேர்ந்த recursive resolver-க்கு DoH பயன்படுத்துவது வேறொரு பகுதியைப் பாதுகாக்கும்.'},
    failure:{en:'After a key change, validating resolvers return SERVFAIL while a nonvalidating lookup still returns addresses. A stale parent DS or expired signature is a better hypothesis than generic packet loss. Inspect DNSKEY, DS, RRSIG timing, and resolver diagnostics; disabling validation may hide the symptom while discarding the protection that revealed the inconsistency.',ta:'Key மாற்றத்துக்குப் பிறகு validating resolvers SERVFAIL தருகின்றன; nonvalidating lookup address தருகிறது. பொதுவான packet loss-ஐவிட பழைய parent DS அல்லது expired signature நல்ல சந்தேகம். DNSKEY, DS, RRSIG நேரம், resolver diagnostics பார்க்கவும்; validation நிறுத்துவது அறிகுறியை மறைத்தாலும் முரண்பாட்டைக் கண்ட பாதுகாப்பையும் இழக்கச் செய்யும்.'},
    lab:{commands:'dig example.com SOA\ndig example.com NS\ndig org DS +dnssec\ndig org DNSKEY +dnssec',guidance:{en:'Use dig on a network that permits DNS. These bounded read-only public lookups inspect records without altering zones; local resolvers may filter DNSSEC material.',ta:'DNS அனுமதிக்கும் network-ல் dig பயன்படுத்தவும். இந்த வரம்புள்ள public read-only queries zones மாற்றாது; local resolver DNSSEC தகவலை வடிகட்டலாம்.'},expected:{en:'SOA and NS illustrate authority data; DNSSEC queries may show RRSIG and key material. The DO request does not itself prove that dig validated the chain, and AD depends on the resolver and trust path.',ta:'SOA, NS authority data காட்டும்; DNSSEC queries RRSIG, keys காட்டலாம். DO request மட்டுமே dig chain validate செய்தது என்பதல்ல; AD resolver, trust path சார்ந்தது.'},cleanup:{en:'No zone, resolver, browser, or trust-anchor settings are changed.',ta:'Zone, resolver, browser, trust-anchor settings எதுவும் மாற்றப்படாது.'}},
    questions:[
      {question:{en:'Why can ns1.lab.example.test need glue in its parent delegation?',ta:'Parent delegation-ல் ns1.lab.example.test-க்கு glue ஏன் தேவைப்படலாம்?'},options:{en:['To break an in-bailiwick lookup dependency','To encrypt every query','To replace all child zone data'],ta:['அதே பகுதியின் circular lookup சார்பைத் தவிர்க்க','எல்லா query-யையும் encrypt செய்ய','Child zone data முழுவதையும் மாற்ற']},answer:0,explanation:{en:'The server name is inside the zone being delegated, so an initial address hint can be necessary.',ta:'Server பெயர் delegate செய்யும் zone-க்குள்ளேயே இருப்பதால் தொடக்க address உதவி தேவைப்படலாம்.'}},
      {question:{en:'Does DoH by itself validate authoritative DNSSEC signatures?',ta:'DoH தானாக authoritative DNSSEC signatures validate செய்யுமா?'},options:{en:['No, transport security and DNSSEC validation are separate','Yes, HTTPS signs every RRset','Only if the query is an A record'],ta:['இல்லை; transport security, DNSSEC validation தனித்தவை','ஆம்; HTTPS எல்லா RRsets-க்கும் sign செய்யும்','Query A record என்றால் மட்டும்']},answer:0,explanation:{en:'HTTPS authenticates the resolver connection; DNSSEC validates DNS data under its own chain.',ta:'HTTPS resolver connection authenticate செய்யும்; DNSSEC தனி chain மூலம் DNS data validate செய்யும்.'}},
      {question:{en:'Only validating clients fail after a signing-key rollover. What should be checked first?',ta:'Signing-key rollover பிறகு validating clients மட்டும் தோற்றால் முதலில் எதைப் பார்ப்பது?'},options:{en:['Parent DS and child DNSKEY/signature consistency','Ethernet cable color','HTTP compression ratio'],ta:['Parent DS, child DNSKEY/signature பொருத்தம்','Ethernet cable நிறம்','HTTP compression விகிதம்']},answer:0,explanation:{en:'The selective failure points toward the validation chain rather than a universal connectivity outage.',ta:'தேர்ந்தெடுத்த இந்தத் தோல்வி முழுத் தொடர்புக் கோளாறைவிட validation chain-ஐச் சுட்டுகிறது.'}}
    ],refs:[['DNS concepts and facilities','https://www.rfc-editor.org/rfc/rfc1034.html'],['DNSSEC protocol modifications','https://www.rfc-editor.org/rfc/rfc4035.html'],['DNS over HTTPS','https://www.rfc-editor.org/rfc/rfc8484.html']]
  },
  {
    id:42,module:10,model:'services',
    title:{en:'HTTP cookies, CORS, and WebSocket boundaries',ta:'HTTP cookies, CORS, WebSocket எல்லைகள்'},
    summary:{en:'Separate browser storage, cross-origin response visibility, and bidirectional messaging while tracing the credential and authorization checks that each application still needs.',ta:'Browser storage, cross-origin response படிக்கும் அனுமதி, இருதிசை messaging ஆகியவற்றைப் பிரித்து ஒவ்வொரு application-க்கும் தேவைப்படும் credential, authorization சோதனைகளைப் பின்தொடர்வோம்.'},
    prerequisites:{en:'HTTP fields and status codes, HTTPS, browser origins, and application authentication.',ta:'HTTP fields, status codes, HTTPS, browser origins, application authentication தெரிந்திருக்க வேண்டும்.'},
    objectives:{en:['Explain cookie scope and security attributes.','Predict credentialed CORS and preflight outcomes.','Distinguish WebSocket upgrade from application authorization.'],ta:['Cookie scope, security attributes விளக்குதல்.','Credentials உள்ள CORS, preflight முடிவுகளைக் கணித்தல்.','WebSocket upgrade-ஐ application authorization-லிருந்து பிரித்தறிதல்.']},
    sections:[
      {heading:{en:'Cookies are scoped state, not automatic trust',ta:'Cookies வரம்புள்ள state; தானியக்க நம்பிக்கை அல்ல'},body:{en:'A server uses Set-Cookie to ask a browser to store state and later send a Cookie field on matching requests. Host/domain, path, expiry, Secure, HttpOnly, and SameSite affect different behaviors. Secure restricts transport to secure contexts as defined by browser rules; HttpOnly prevents ordinary script access rather than preventing the browser from sending the cookie. SameSite helps constrain cross-site use but is not equivalent to the origin tuple of scheme, host, and port. Server-side session validation and CSRF defenses remain necessary.',ta:'Server Set-Cookie மூலம் browser-ல் state சேமித்து பொருந்தும் request-ல் Cookie field அனுப்பச் சொல்கிறது. Host/domain, path, expiry, Secure, HttpOnly, SameSite தனித்தனி நடத்தைகளை நிர்ணயிக்கும். Secure browser விதிப்படி secure transport-ஐ வரம்பிடும்; HttpOnly சாதாரண script படிப்பதைத் தடுக்கும், browser அனுப்புவதை அல்ல. SameSite cross-site பயன்பாட்டைக் கட்டுப்படுத்த உதவும்; scheme, host, port கொண்ட origin tuple-க்கு அது சமமல்ல. Server session validation, CSRF தடுப்பு இன்னும் தேவை.'}},
      {heading:{en:'CORS governs browser response exposure',ta:'CORS browser பதிலைப் படிக்க அனுமதிக்கிறது'},body:{en:'The same-origin policy restricts script access to many cross-origin responses. CORS lets a server authorize selected origins through response fields, and some requests require an OPTIONS preflight before the real operation. With credentialed requests, Access-Control-Allow-Origin cannot simply be an asterisk; the allowed origin must be explicit and credential permission must be appropriate. CORS is not general authentication or a network firewall. Some cross-origin requests can reach the server even when script cannot read the response, so mutation endpoints need their own protection.',ta:'Same-origin policy பல cross-origin responses-ஐ script படிப்பதைத் தடுக்கும். CORS response fields மூலம் server தேர்ந்த origins-க்கு அனுமதி தருகிறது; சில requests-க்கு உண்மையான செயலுக்கு முன் OPTIONS preflight வேண்டும். Credentials உள்ள request-ல் Access-Control-Allow-Origin வெறும் asterisk ஆக முடியாது; origin வெளிப்படையாகவும் credentials அனுமதி சரியாகவும் இருக்க வேண்டும். CORS பொதுவான authentication அல்லது firewall அல்ல. Script பதில் படிக்க முடியாவிட்டாலும் சில requests server அடையலாம்; மாற்றம் செய்யும் endpoints தனிப் பாதுகாப்பு வேண்டும்.'}},
      {heading:{en:'WebSocket creates a persistent message channel',ta:'WebSocket நீடித்த message channel உருவாக்கும்'},body:{en:'The familiar HTTP/1.1 WebSocket opening uses Upgrade and a successful 101 response, followed by framed messages rather than ordinary HTTP response bodies. Client frames are masked, but masking is not encryption; wss uses TLS. The handshake’s Accept calculation is not user authentication. Servers should evaluate Origin and credentials, authorize subscriptions or actions, bound message sizes, and handle ping/pong, closure, and backpressure. A reverse proxy must support the required protocol behavior and idle lifetime or a working handshake can be followed by unexpected disconnects.',ta:'பழக்கமான HTTP/1.1 WebSocket தொடக்கம் Upgrade, வெற்றியான 101 response பயன்படுத்தும்; பின்னர் வழக்கமான HTTP body அல்ல framed messages வரும். Client frames masked ஆகும்; அது encryption அல்ல; wss TLS பயன்படுத்தும். Handshake Accept கணக்கு user authentication அல்ல. Server Origin, credentials ஆய்ந்து subscriptions, actions authorize செய்து message அளவு வரம்பு, ping/pong, close, backpressure கையாள வேண்டும். Reverse proxy protocol, idle lifetime ஆதரிக்காவிட்டால் நல்ல handshake பிறகும் எதிர்பாராத disconnect வரலாம்.'}}
    ],
    example:{en:'A page at https://app.example.test calls https://api.example.test/profile with cookies. The origins differ by host even though the names share a suffix. A permitted credentialed response can name https://app.example.test as its allowed origin and explicitly allow credentials; varying that response by Origin requires correct cache handling. A separate WebSocket at wss://api.example.test/events must validate the session and authorize which account’s events are delivered after the opening handshake.',ta:'https://app.example.test பக்கம் cookies உடன் https://api.example.test/profile அழைக்கிறது. Suffix ஒன்றாக இருந்தாலும் host வேறாக இருப்பதால் origins வேறு. அனுமதித்த credentialed response allowed origin ஆக https://app.example.test குறிப்பிட்டு credentials அனுமதிக்கலாம்; Origin-க்கேற்ப பதில் மாறினால் cache சரியாகக் கையாள வேண்டும். தனி wss://api.example.test/events WebSocket session validate செய்து எந்த account events வழங்கலாம் என்று handshake பிறகும் authorize செய்ய வேண்டும்.'},
    failure:{en:'A command-line client succeeds while the browser reports CORS failure. Inspect preflight status, allowed origin, methods, headers, credential mode, and redirects. Curl does not enforce the browser’s same-origin policy, so its success demonstrates a reachable HTTP endpoint rather than proving a correct CORS configuration.',ta:'Command-line client வெற்றி; browser CORS failure கூறுகிறது. Preflight status, allowed origin, methods, headers, credential mode, redirects பார்க்கவும். Curl browser same-origin policy அமல்படுத்தாது; அதன் வெற்றி HTTP endpoint reachable என்பதைத்தான் காட்டும், CORS சரியென்பதை அல்ல.'},
    lab:{commands:"python3 - <<'PY'\nfrom http.cookies import SimpleCookie\nfrom urllib.parse import urlsplit\nc=SimpleCookie(); c.load('sid=demo; Path=/; Secure; HttpOnly; SameSite=Lax')\nm=c['sid']\nprint(m['path'],bool(m['secure']),bool(m['httponly']),m['samesite'])\nfor u in ['https://app.example.test','https://api.example.test','https://app.example.test:8443']:\n    p=urlsplit(u); print((p.scheme,p.hostname,p.port or 443))\nPY",guidance:{en:'Python 3 parses an invented cookie and origin tuples locally. No real credentials are used, and this parser does not simulate browser cookie or CORS enforcement.',ta:'Python 3 கற்பனை cookie, origin tuples-ஐ உள்ளூரில் parse செய்கிறது. உண்மையான credentials இல்லை; browser cookie அல்லது CORS enforcement-ஐ இந்த parser பின்பற்றாது.'},expected:{en:'Cookie attributes print /, True, True, Lax. All three origin tuples differ by host or port.',ta:'Cookie attributes /, True, True, Lax என்று வரும். மூன்று origin tuples-மும் host அல்லது port-ல் வேறுபடும்.'},cleanup:{en:'No browser storage, servers, files, or cookies are created.',ta:'Browser storage, servers, files, cookies உருவாக்கப்படாது; cleanup இல்லை.'}},
    questions:[
      {question:{en:'Can credentialed CORS use Access-Control-Allow-Origin: *?',ta:'Credentials உள்ள CORS-ல் Access-Control-Allow-Origin: * பயன்படுத்தலாமா?'},options:{en:['No, an explicit allowed origin is required','Yes, always','Only when cookies are HttpOnly'],ta:['இல்லை; வெளிப்படையான allowed origin தேவை','ஆம்; எப்போதும்','Cookies HttpOnly என்றால் மட்டும்']},answer:0,explanation:{en:'The browser’s credentialed CORS checks reject wildcard origin permission.',ta:'Browser credentialed CORS சோதனை wildcard origin அனுமதியை நிராகரிக்கும்.'}},
      {question:{en:'Does WebSocket client masking encrypt the payload?',ta:'WebSocket client masking payload encrypt செய்யுமா?'},options:{en:['No, use TLS through wss for channel encryption','Yes, the mask is a secret session key','Only for binary frames'],ta:['இல்லை; channel encryption-க்கு wss வழி TLS தேவை','ஆம்; mask ரகசிய session key','Binary frames-க்கு மட்டும்']},answer:0,explanation:{en:'Masking serves protocol safety goals and is not cryptographic confidentiality.',ta:'Masking protocol பாதுகாப்புப் பணிக்கானது; cryptographic confidentiality அல்ல.'}},
      {question:{en:'Curl succeeds but browser script cannot read a response. What should be inspected?',ta:'Curl வெற்றியடைந்தும் browser script பதில் படிக்கவில்லை. எதை ஆய்வது?'},options:{en:['CORS fields and any preflight exchange','Only Ethernet collision counters','Only the TCP initial sequence number'],ta:['CORS fields, preflight பரிமாற்றம்','Ethernet collision counters மட்டும்','TCP initial sequence number மட்டும்']},answer:0,explanation:{en:'Browser-origin enforcement can fail after the network and HTTP exchange succeed.',ta:'Network, HTTP பரிமாற்றம் வென்ற பிறகும் browser-origin enforcement தோற்கலாம்.'}}
    ],refs:[['HTTP state management','https://www.rfc-editor.org/rfc/rfc6265.html'],['Fetch standard: CORS protocol','https://fetch.spec.whatwg.org/'],['WebSocket protocol','https://www.rfc-editor.org/rfc/rfc6455.html']]
  },
  {
    id:43,module:10,model:'tls',
    title:{en:'TLS PKI, session resumption, and replayable early data',ta:'TLS PKI, session resumption, replay ஆகக்கூடிய early data'},
    summary:{en:'Separate certificate identity checks, handshake proof, and resumed key establishment, then decide which operations can tolerate the weaker replay guarantees of TLS 1.3 early data.',ta:'Certificate identity சோதனை, handshake proof, resumed key establishment ஆகியவற்றைப் பிரித்து TLS 1.3 early data-வின் குறைந்த replay பாதுகாப்பை எந்தச் செயல்கள் தாங்கலாம் என்று ஆராய்வோம்.'},
    prerequisites:{en:'TLS handshakes, asymmetric signatures, symmetric encryption, and HTTP request semantics.',ta:'TLS handshake, asymmetric signatures, symmetric encryption, HTTP request semantics தெரிந்திருக்க வேண்டும்.'},
    objectives:{en:['Describe path validation and hostname verification separately.','Explain resumption tickets and PSK with fresh key exchange.','Identify replay-sensitive operations and realistic latency savings.'],ta:['Path validation, hostname verification தனித்தனியாக விளக்குதல்.','Resumption tickets, fresh key exchange உடன் PSK விளக்குதல்.','Replay பாதிக்கும் operations, உண்மையான latency சேமிப்பைக் கண்டறிதல்.']},
    sections:[
      {heading:{en:'A certificate chain is only part of authentication',ta:'Certificate chain authentication-ன் ஒரு பகுதி மட்டுமே'},body:{en:'A client builds and validates a certificate path to an accepted trust anchor, considering validity periods, constraints, key usage, and local policy. It also checks that the service identity matches the requested name; a chain trusted for one name is not automatically trusted for every host. The handshake verifies possession of the corresponding private key and binds authentication to negotiated parameters. Revocation handling and trust stores vary by client. SNI helps select a virtual service, but sending SNI alone does not verify its certificate.',ta:'Client ஏற்ற trust anchor வரை certificate path அமைத்து validity காலம், constraints, key usage, local policy ஆய்வு செய்கிறது. கேட்ட பெயருக்கு service identity பொருந்துகிறதா என்றும் பார்க்கும்; ஒரு பெயருக்கான trusted chain எல்லா hosts-க்கும் அனுமதி அல்ல. Handshake சம்பந்தப்பட்ட private key வைத்திருப்பதை நிரூபித்து negotiated parameters உடன் authentication இணைக்கிறது. Revocation கையாளுதல், trust stores client-ஐச் சாரும். SNI virtual service தேர உதவும்; SNI அனுப்புவது மட்டுமே certificate verification அல்ல.'}},
      {heading:{en:'Resumption reuses a security relationship',ta:'Resumption பாதுகாப்பு உறவை மீண்டும் பயன்படுத்துகிறது'},body:{en:'TLS 1.3 servers can issue tickets that allow later PSK-based resumption. A ticket is sensitive state, not a public identity certificate, and deployment choices govern its lifetime and acceptance across servers. Resumption can combine the PSK with a fresh Diffie-Hellman exchange for forward secrecy of the resulting connection keys. It does not mean application authorization can be skipped: a user account may have been disabled since the ticket was issued. Ticket-key rotation and consistent policy across a cluster affect both availability and security.',ta:'TLS 1.3 server tickets வழங்கி பின்னர் PSK அடிப்படையில் resume செய்ய அனுமதிக்கலாம். Ticket முக்கியமான state; public identity certificate அல்ல; அதன் lifetime, servers இடையே ஏற்றல் deployment தேர்வு. Resumption PSK உடன் fresh Diffie-Hellman சேர்த்து புதிய connection keys-க்கு forward secrecy தரலாம். அதனால் application authorization தவிர்க்க முடியாது; ticket வழங்கியபின் user account நிறுத்தப்பட்டிருக்கலாம். Ticket-key rotation, cluster முழுவதும் ஒரே policy இருப்பது availability, security இரண்டையும் பாதிக்கும்.'}},
      {heading:{en:'Early data trades delay for weaker guarantees',ta:'Early data delay குறைத்தாலும் பாதுகாப்பு வேறுபடும்'},body:{en:'With eligible resumption state, a client may send 0-RTT application data before receiving the server’s new handshake flight. Those bytes are encrypted but can be replayed, and they do not have the same forward-secrecy properties as fresh key-exchange traffic. Anti-replay measures have deployment limits, especially across distributed servers. Applications must explicitly decide which operations are replay-safe and handle rejection or retry without duplicating effects. HTTP 425 can signal that a server is unwilling to risk processing a request as early data.',ta:'தகுந்த resumption state இருந்தால் server-ன் புதிய handshake flight வரும்முன் client 0-RTT application data அனுப்பலாம். Bytes encrypted என்றாலும் replay செய்யப்படலாம்; fresh key-exchange traffic போலவே forward-secrecy பண்பு கிடையாது. குறிப்பாக distributed servers-ல் anti-replay நடைமுறைக்கு வரம்புகள் உள்ளன. எந்த operations replay-safe என்பதை application வெளிப்படையாகத் தீர்மானித்து rejection, retry வந்தாலும் விளைவுகள் இரட்டிக்காமல் கையாள வேண்டும். Early data request process செய்வதற்கான அபாயத்தை ஏற்காத server HTTP 425 சொல்லலாம்.'}}
    ],
    example:{en:'At 80 ms RTT, a simple timing model places fresh TLS 1.3 application sending after roughly one TLS RTT once transport is ready. Accepted early data can start without that TLS wait, saving about 80 ms in this model, not eliminating DNS or transport setup. Reading a static public asset may be suitable under application policy; transferring money or consuming a one-use token is replay-sensitive. Even a GET endpoint needs review if it triggers side effects or exposes sensitive timing behavior.',ta:'80 ms RTT-ல் transport தயாரானபின் fresh TLS 1.3 application அனுப்ப சுமார் ஒரு TLS RTT தேவை என எளிய model கொள்வோம். ஏற்கப்பட்ட early data அந்தக் காத்திருப்பின்றி தொடங்கி சுமார் 80 ms சேமிக்கலாம்; DNS, transport setup நீங்காது. Static public asset படித்தல் policy-க்கு ஏற்ப பொருந்தலாம்; பணமாற்றம், ஒருமுறை token செலவிடுதல் replay பாதிக்கும். GET endpoint-க்கும் side effects அல்லது sensitive timing இருந்தால் ஆய்வு தேவை.'},
    failure:{en:'A resumed payment request is retried after early-data rejection and the application charges twice because it lacks an idempotency mechanism. Encryption did not prevent duplicate effects. Diagnose request identifiers, server processing logs, retry policy, and early-data acceptance together; disable early data for that operation until the application semantics are safe.',ta:'Early-data rejection பிறகு resumed payment மீண்டும் அனுப்பப்பட்டு idempotency இல்லாததால் இருமுறை charge ஆகிறது. Encryption இரட்டை விளைவைத் தடுக்கவில்லை. Request identifiers, server logs, retry policy, early-data acceptance சேர்த்து ஆய்வு செய்யவும்; application semantics பாதுகாப்பாகும்வரை அந்த operation-க்கு early data அனுமதிக்கக்கூடாது.'},
    lab:{commands:"python3 - <<'PY'\nrtt_ms=80\ntransport_ready_ms=0\nprint('fresh_TLS_application_start_ms',transport_ready_ms+rtt_ms)\nprint('accepted_early_data_start_ms',transport_ready_ms)\nfor op,replay_safe in [('static_asset',True),('payment',False),('consume_one_use_token',False)]:\n    print(op,'candidate_for_review' if replay_safe else 'exclude_from_early_data')\nPY\nopenssl version",guidance:{en:'Use a local Python 3 timing model and inspect the OpenSSL version. These invented operation labels encode explicit assumptions, not an automatic security classifier.',ta:'உள்ளூர் Python 3 timing model இயக்கி OpenSSL version பார்க்கவும். கற்பனை operation பெயர்களின் முடிவுகள் வெளிப்படையான ஊகங்கள்; தானியக்க security classifier அல்ல.'},expected:{en:'The model prints 80 ms versus 0 ms after transport readiness and excludes payment and one-use token consumption. No real TLS session or ticket is generated.',ta:'Transport தயாரானபின் 80 ms, 0 ms என்று வரும்; payment, one-use token செயல்கள் விலக்கப்படும். உண்மையான TLS session, ticket உருவாகாது.'},cleanup:{en:'No certificates, keys, trust stores, or session files are written.',ta:'Certificates, keys, trust stores, session files எழுதப்படாது; cleanup தேவையில்லை.'}},
    questions:[
      {question:{en:'Does sending SNI verify the hostname?',ta:'SNI அனுப்பினாலே hostname verify ஆகுமா?'},options:{en:['No, certificate identity verification is still required','Yes, SNI is a CA signature','Only for wildcard names'],ta:['இல்லை; certificate identity verification இன்னும் தேவை','ஆம்; SNI ஒரு CA signature','Wildcard பெயர்களுக்கு மட்டும்']},answer:0,explanation:{en:'SNI selects a service; authentication checks the identity presented by that service.',ta:'SNI service தேரும்; authentication அந்த service காட்டும் identity சரிபார்க்கும்.'}},
      {question:{en:'What TLS waiting time is saved by accepted early data in the 80 ms model?',ta:'80 ms model-ல் ஏற்கப்பட்ட early data எவ்வளவு TLS காத்திருப்பைச் சேமிக்கும்?'},options:{en:['About 80 ms, with transport already ready','All DNS and network delay','Exactly 800 ms'],ta:['Transport தயாரான நிலையில் சுமார் 80 ms','எல்லா DNS, network delay','சரியாக 800 ms']},answer:0,explanation:{en:'The simplified comparison removes one TLS RTT, not unrelated setup or processing delays.',ta:'எளிய ஒப்பீடு ஒரு TLS RTT-ஐ நீக்கும்; மற்ற setup, processing delays அல்ல.'}},
      {question:{en:'Which operation is most clearly unsafe to replay without extra safeguards?',ta:'கூடுதல் பாதுகாப்பின்றி replay செய்வதில் தெளிவாக அபாயமான operation எது?'},options:{en:['Charging a payment','Fetching a deliberately replay-safe public image','Reading immutable public documentation'],ta:['பணம் charge செய்தல்','Replay-safe எனத் திட்டமிட்ட public image பெறுதல்','மாறாத public ஆவணம் படித்தல்']},answer:0,explanation:{en:'A repeated payment can duplicate an irreversible effect even over encrypted transport.',ta:'Encrypted transport இருந்தாலும் மீண்டும் payment செய்வது திருப்பமுடியாத விளைவை இரட்டிக்கலாம்.'}}
    ],refs:[['TLS 1.3','https://www.rfc-editor.org/rfc/rfc8446.html'],['PKI certificate path validation','https://www.rfc-editor.org/rfc/rfc5280.html'],['Service identity in TLS','https://www.rfc-editor.org/rfc/rfc9525.html'],['HTTP early data','https://www.rfc-editor.org/rfc/rfc8470.html']]
  },
  {
    id:44,module:10,model:'vlan',
    title:{en:'VXLAN overlays, EVPN distribution, and SDN control',ta:'VXLAN overlays, EVPN பகிர்வு, SDN கட்டுப்பாடு'},
    summary:{en:'Follow inner Ethernet through an IP underlay, separate VXLAN encapsulation from EVPN reachability distribution, and reason about the limits of centralized intent.',ta:'Inner Ethernet IP underlay வழியாகச் செல்வதைப் பின்தொடர்ந்து VXLAN encapsulation-ஐ EVPN reachability பகிர்விலிருந்து பிரித்து centralized intent-ன் வரம்புகளை ஆராய்வோம்.'},
    prerequisites:{en:'VLANs, IP routing, BGP attributes, MTU, and MAC learning.',ta:'VLANs, IP routing, BGP attributes, MTU, MAC learning தெரிந்திருக்க வேண்டும்.'},
    objectives:{en:['Identify VTEPs, VNIs, inner frames, and outer headers.','Explain EVPN MAC/IP distribution and BUM handling.','Calculate encapsulation overhead and diagnose underlay dependencies.'],ta:['VTEPs, VNIs, inner frames, outer headers கண்டறிதல்.','EVPN MAC/IP பகிர்வு, BUM கையாளுதல் விளக்குதல்.','Encapsulation overhead கணக்கிட்டு underlay சார்புக் கோளாறுகள் அறிதல்.']},
    sections:[
      {heading:{en:'VXLAN supplies a data-plane wrapper',ta:'VXLAN data-plane உறை வழங்கும்'},body:{en:'A VXLAN tunnel endpoint encapsulates an Ethernet frame inside UDP and IP for transport between VTEPs. The 24-bit VNI identifies an overlay segment, allowing more identifiers than a 12-bit VLAN field, but identifier space is not the same as practical platform capacity. The underlay routes to the outer destination IP and need not learn tenant MAC addresses. Inner tenant addresses can overlap when isolation is correctly implemented. The outer UDP source port can contribute entropy for underlay ECMP distribution.',ta:'VXLAN tunnel endpoint Ethernet frame-ஐ UDP, IP உள்ளே வைத்து VTEPs இடையே அனுப்பும். 24-bit VNI overlay segment குறிக்கும்; 12-bit VLAN field-ஐவிட அதிக identifiers இருந்தாலும் நடைமுறை platform capacity அதுவல்ல. Underlay outer destination IP-க்கு route செய்யும்; tenant MAC கற்க வேண்டியதில்லை. சரியான isolation இருந்தால் inner tenant addresses மீண்டும் பயன்படுத்தலாம். Outer UDP source port underlay ECMP பகிர்வுக்கு entropy தரலாம்.'}},
      {heading:{en:'EVPN distributes overlay reachability',ta:'EVPN overlay reachability பகிர்கிறது'},body:{en:'EVPN uses BGP routes to distribute service reachability and related information. MAC/IP advertisement routes can tell a VTEP which remote endpoint owns a tenant MAC or IP, reducing dependence on data-plane flooding. Inclusive multicast information supports broadcast, unknown-unicast, and multicast delivery arrangements such as ingress replication. Multi-homing adds designated-forwarder and split-horizon procedures. EVPN is not itself the VXLAN encapsulation, and deployments must still agree on VNIs, route targets, gateway behavior, and the supported route types.',ta:'EVPN BGP routes மூலம் service reachability, தொடர்புடைய தகவல் பகிர்கிறது. MAC/IP advertisement routes மூலம் tenant MAC அல்லது IP எந்த remote endpoint-ல் உள்ளது என்று VTEP அறிந்து flooding சார்பைக் குறைக்கலாம். Inclusive multicast தகவல் broadcast, unknown-unicast, multicast delivery-க்கு ingress replication போன்ற முறைகளுக்கு உதவும். Multi-homing designated-forwarder, split-horizon நடைமுறைகள் சேர்க்கும். EVPN தானே VXLAN encapsulation அல்ல; VNIs, route targets, gateway நடத்தை, ஆதரிக்கும் route types ஒத்திருக்க வேண்டும்.'}},
      {heading:{en:'Intent needs observable realization',ta:'Intent உண்மையில் அமலானதற்குச் சான்று தேவை'},body:{en:'SDN separates aspects of control or intent from device forwarding, but implementations range from controller APIs to distributed routing plus orchestration. A successful API response may only mean desired state was accepted, not that every VTEP installed it. Reconcile desired, operational, and forwarding state, and consider controller unavailability and stale entries. An overlay cannot repair a missing underlay route, blocked UDP transport, or insufficient MTU. Policy must be enforced at defined boundaries because VXLAN alone supplies no encryption.',ta:'SDN control அல்லது intent-ன் சில பகுதிகளை device forwarding-லிருந்து பிரிக்கும்; controller API முதல் distributed routing உடன் orchestration வரை implementations மாறும். API வெற்றி desired state ஏற்றதைக் காட்டலாம்; எல்லா VTEPs-லும் நிறுவியதைக் கட்டாயம் காட்டாது. Desired, operational, forwarding state ஒப்பிட்டு controller கிடைக்காமை, பழைய entries கவனிக்க வேண்டும். Missing underlay route, UDP தடுப்பு, குறைந்த MTU ஆகியவற்றை overlay சரிசெய்யாது. VXLAN தனியே encryption தராததால் policy குறிப்பிட்ட எல்லைகளில் அமலாக வேண்டும்.'}}
    ],
    example:{en:'Two VTEPs at 192.0.2.11 and 192.0.2.12 carry VNI 5000. A 1500-byte inner IP packet plus a 14-byte inner Ethernet header, 8-byte VXLAN header, 8-byte UDP header, and 20-byte outer IPv4 header yields a 1550-byte outer IP packet, excluding inner FCS. The underlay therefore needs at least that IP MTU for this unfragmented example. Outer IPv6 adds twenty more bytes, and VLAN tags or other headers change the budget.',ta:'192.0.2.11, 192.0.2.12 VTEPs VNI 5000 எடுத்துச் செல்கின்றன. 1500-byte inner IP, 14-byte inner Ethernet, 8-byte VXLAN, 8-byte UDP, 20-byte outer IPv4 சேர்த்து inner FCS தவிர 1550-byte outer IP packet கிடைக்கும். Fragmentation இல்லாத இந்த எடுத்துக்காட்டுக்கு underlay IP MTU குறைந்தது அவ்வளவு தேவை. Outer IPv6 மேலும் இருபது bytes சேர்க்கும்; VLAN tags, மற்ற headers கணக்கை மாற்றும்.'},
    failure:{en:'Small tenant pings work but large transfers stall after enabling the overlay. Verify the complete encapsulated MTU budget and returned ICMP errors before changing EVPN import policy. Another pattern is correct underlay connectivity but missing tenant MAC routes due to mismatched route targets; these failures require different evidence and repairs.',ta:'Overlay தொடங்கியபின் சிறிய tenant ping இயங்கியும் பெரிய transfer நிற்கிறது. EVPN import policy மாற்றும்முன் முழு encapsulated MTU கணக்கு, திரும்பும் ICMP errors பார்க்கவும். வேறு சூழலில் underlay சரியாக இருந்தும் route targets பொருந்தாததால் tenant MAC routes வராது; இரண்டுக்கும் வேறு சான்றும் தீர்வும் தேவை.'},
    lab:{commands:"ip -d link show type vxlan\npython3 - <<'PY'\ninner_ip=1500\nfor outer_ip in (20,40):\n    outer_packet=inner_ip+14+8+8+outer_ip\n    print('outer_IP_header',outer_ip,'required_IP_MTU',outer_packet)\nprint('VNI_bit_patterns',2**24)\nPY",guidance:{en:'Linux iproute2 inspects only existing VXLAN interfaces. Python 3 calculates a simplified untagged packet budget; it does not test a real path or create a tunnel.',ta:'Linux iproute2 ஏற்கெனவே உள்ள VXLAN interfaces மட்டும் பார்க்கும். Python 3 untagged packet-ன் எளிய கணக்கைச் செய்கிறது; உண்மைப் பாதை சோதனையோ tunnel உருவாக்கமோ இல்லை.'},expected:{en:'Required outer IP sizes are 1550 and 1570 bytes. The identifier calculation prints 16777216 bit patterns, not a promise of that many usable deployed segments.',ta:'Outer IP அளவுகள் 1550, 1570 bytes. Identifier கணக்கு 16777216 bit patterns காட்டும்; அத்தனை deployed segments பயன்படுத்தலாம் என்ற உறுதி அல்ல.'},cleanup:{en:'No VTEPs, VNIs, BGP sessions, or controller objects are created.',ta:'VTEPs, VNIs, BGP sessions, controller objects உருவாக்கப்படாது.'}},
    questions:[
      {question:{en:'What outer IPv4 packet size results from the worked example?',ta:'எடுத்துக்காட்டின் outer IPv4 packet அளவு என்ன?'},options:{en:['1550 bytes','1500 bytes including all tunnel overhead','1518 bytes in every deployment'],ta:['1550 bytes','எல்லா tunnel overhead உட்பட 1500 bytes','எல்லா deployment-லும் 1518 bytes']},answer:0,explanation:{en:'Add 14+8+8+20 bytes to the inner 1500-byte IP packet.',ta:'Inner 1500-byte IP packet-க்கு 14+8+8+20 bytes சேர்க்க வேண்டும்.'}},
      {question:{en:'Which function does EVPN provide in this design?',ta:'இந்த வடிவத்தில் EVPN என்ன வழங்குகிறது?'},options:{en:['Control-plane distribution of overlay reachability','Automatic payload encryption','Replacement for every underlay route'],ta:['Overlay reachability control-plane பகிர்வு','தானியக்க payload encryption','எல்லா underlay routes-க்கும் மாற்று']},answer:0,explanation:{en:'VXLAN encapsulates traffic, while EVPN distributes service reachability information.',ta:'VXLAN traffic encapsulate செய்கிறது; EVPN service reachability தகவல் பகிர்கிறது.'}},
      {question:{en:'Small packets work but large packets stall. Which hypothesis fits first?',ta:'சிறிய packets இயங்கியும் பெரியவை நிற்கின்றன. முதலில் பொருந்தும் சந்தேகம் எது?'},options:{en:['Encapsulation exceeds path MTU and feedback is missing','Every VNI must equal a VLAN number','BGP always rejects large application messages'],ta:['Encapsulation path MTU மீறி feedback வரவில்லை','ஒவ்வொரு VNI-யும் VLAN எண்ணாக இருக்க வேண்டும்','BGP பெரிய application messages நிராகரிக்கும்']},answer:0,explanation:{en:'A size-dependent failure points toward packet-size handling rather than an automatic control-plane failure.',ta:'அளவுக்கேற்ப தோல்வி packet-size கையாளுதலைச் சுட்டுகிறது; தானாக control-plane கோளாறு அல்ல.'}}
    ],refs:[['VXLAN framework','https://www.rfc-editor.org/rfc/rfc7348.html'],['EVPN routes and procedures','https://www.rfc-editor.org/rfc/rfc7432.html'],['EVPN network virtualization overlays','https://www.rfc-editor.org/rfc/rfc8365.html']]
  },
  {
    id:45,module:10,model:'firewall',
    title:{en:'Cloud VPC routing and load-balancer health paths',ta:'Cloud VPC routing, load-balancer health பாதைகள்'},
    summary:{en:'Reason through cloud routes, stateful and stateless controls, and load-balancer target selection using explicit provider semantics rather than treating a private address as a security guarantee.',ta:'Private address பாதுகாப்பு உறுதி எனக் கருதாமல் provider விதிகளின் அடிப்படையில் cloud routes, stateful/stateless கட்டுப்பாடு, load-balancer target தேர்வு ஆகியவற்றை ஆராய்வோம்.'},
    prerequisites:{en:'Subnets, routing, NAT, firewalls, TLS termination, and HTTP health checks.',ta:'Subnets, routing, NAT, firewalls, TLS termination, HTTP health checks தெரிந்திருக்க வேண்டும்.'},
    objectives:{en:['Trace routes and policy on both directions of a cloud flow.','Distinguish listener, target, and health-check paths.','Recognize provider-specific controls and shared failure domains.'],ta:['Cloud flow-ன் இருதிசையிலும் routes, policy பின்தொடர்தல்.','Listener, target, health-check பாதைகளை வேறுபடுத்துதல்.','Provider சார்ந்த controls, பொதுவான failure domains அறிதல்.']},
    sections:[
      {heading:{en:'A VPC is a routing and policy environment',ta:'VPC ஒரு routing, policy சூழல்'},body:{en:'Cloud virtual networks provide address ranges, subnets, route associations, and connectivity attachments through provider abstractions. A subnet being called public or private usually describes its routing and exposure design rather than a different IP packet format. Internet access may require an appropriate gateway, address mapping, and policy in addition to a default route. Peering or transit attachments introduce their own propagation rules and overlap constraints. Check the actual provider documentation; similar names across clouds do not guarantee identical forwarding or security behavior.',ta:'Cloud virtual networks provider abstractions மூலம் address ranges, subnets, route associations, connectivity attachments தருகின்றன. Public அல்லது private subnet என்பது பொதுவாக routing, exposure வடிவமைப்பு; வேறு IP packet வடிவம் அல்ல. Internet access-க்கு default route மட்டுமின்றி பொருத்தமான gateway, address mapping, policy தேவைப்படலாம். Peering, transit attachments-க்கு தனி propagation விதி, overlap வரம்புகள் உண்டு. Provider documentation பார்க்க வேண்டும்; clouds-ல் ஒரே போன்ற பெயர்கள் ஒரே forwarding, security நடத்தை உறுதிப்படுத்தாது.'}},
      {heading:{en:'Stateful and stateless controls have different return rules',ta:'Stateful, stateless controls-ன் return விதிகள் வேறு'},body:{en:'In AWS VPC terminology, security groups are stateful allow-rule controls associated with network interfaces, while network ACLs are stateless subnet-boundary controls with ordered allow and deny rules. Accepted connection return traffic can be recognized by a security group, whereas an ACL must independently permit the return direction. Ephemeral destination ports on replies therefore matter. These are AWS-specific teaching semantics, not a claim about every cloud. Neither rule type creates a route or guarantees that the application is listening.',ta:'AWS VPC சொற்களில் security groups network interfaces உடன் தொடர்புடைய stateful allow-rule controls; network ACLs subnet எல்லையில் ordered allow/deny கொண்ட stateless controls. Security group ஏற்கப்பட்ட connection-ன் return traffic அடையாளம் காணலாம்; ACL return திசையைத் தனியாக அனுமதிக்க வேண்டும். எனவே reply-ன் ephemeral destination ports முக்கியம். இவை AWS பயிற்சி விதிகள்; எல்லா clouds-க்கும் பொதுவிதி அல்ல. எந்த rule-மும் route உருவாக்காது; application கேட்கிறதா என்றும் உறுதிப்படுத்தாது.'}},
      {heading:{en:'A load balancer has several independent conversations',ta:'Load balancer-க்கு பல தனி உரையாடல்கள் உள்ளன'},body:{en:'A listener accepts client traffic and a target group identifies eligible backends. Layer-seven proxies can terminate TLS and make new backend connections, while other balancing modes preserve different transport properties. Health checks may use a different port, protocol, path, host expectation, or source from real clients. Passing a simple health endpoint does not prove database-backed requests work. Zone placement, target registration, connection draining, timeouts, and provider-specific all-unhealthy behavior affect failures. Use both health evidence and a real application transaction when verifying service.',ta:'Listener client traffic ஏற்கிறது; target group தகுந்த backends காட்டும். Layer-seven proxy TLS முடித்து புதிய backend connections செய்யலாம்; வேறு modes வேறு transport பண்புகள் காக்கும். Health check port, protocol, path, host எதிர்பார்ப்பு, source ஆகியவை client-இலிருந்து மாறலாம். எளிய health endpoint வெற்றி database request வெற்றியை நிரூபிக்காது. Zone placement, registration, draining, timeouts, எல்லா targets unhealthy ஆனபோதான provider நடத்தை தோல்வியை மாற்றும். Health சான்றுடன் உண்மையான application transaction-மும் சரிபார்க்க வேண்டும்.'}}
    ],
    example:{en:'A public HTTPS listener on port 443 proxies to private targets on port 8080, with an HTTP health check on /ready at the same target port. The target should accept the balancer’s permitted source context on 8080, not arbitrary public clients. A client connection from port 53000 to 443 receives replies destined to 53000, which a stateless boundary must allow separately. If TLS terminates at the balancer, backend encryption and identity checks are separate design decisions.',ta:'Public HTTPS listener port 443 private targets port 8080-க்கு proxy செய்கிறது; அதே target port-ல் /ready HTTP health check நடக்கும். Target balancer-ன் அனுமதித்த source context-ஐ 8080-ல் ஏற்க வேண்டும்; எல்லா public clients-ஐ அல்ல. Client port 53000-லிருந்து 443-க்கு இணைந்தால் replies destination 53000; stateless எல்லை இதைத் தனியாக அனுமதிக்க வேண்டும். Balancer-ல் TLS முடிந்தால் backend encryption, identity checks தனி வடிவமைப்பு முடிவுகள்.'},
    failure:{en:'Targets are unhealthy despite local curl succeeding on each VM. Inspect whether the process binds only to loopback, the health-check source is permitted, the configured path returns an accepted status, and the correct port is registered. Opening every inbound port is not a diagnosis and can leave unnecessary exposure after the actual mistake is fixed.',ta:'VM-ல் local curl வென்றும் targets unhealthy. Process loopback-க்கு மட்டும் bind ஆனதா, health-check source அனுமதியா, path ஏற்ற status தருகிறதா, சரியான port register ஆனதா பார்க்கவும். எல்லா inbound ports திறப்பது diagnosis அல்ல; உண்மைத் தவறு சரியானபின்பும் தேவையற்ற exposure விடலாம்.'},
    lab:{commands:"python3 - <<'PY'\nclient=('198.51.100.20',53000)\nlistener=('203.0.113.10',443)\ntarget=('10.0.2.7',8080)\nprint('client_flow',client,'->',listener)\nprint('reply_destination_port',client[1])\nprint('backend_destination',target,'health_path','/ready')\nPY\nss -ltn",guidance:{en:'This local model uses documentation and private addresses without connecting to them. Linux ss inspects listeners on your current machine, not any cloud account.',ta:'உள்ளூர் model documentation, private addresses பயன்படுத்துகிறது; அவற்றுக்கு connect செய்யாது. Linux ss தற்போதைய கணினி listeners மட்டும் பார்க்கும்; cloud account அல்ல.'},expected:{en:'The return destination is port 53000 and the backend destination is port 8080. A loopback-only listener is distinguishable from one bound to other local addresses.',ta:'Return destination 53000, backend destination 8080 வரும். Loopback-only listener-ஐ மற்ற local addresses-ல் bind ஆனதிலிருந்து வேறுபடுத்தலாம்.'},cleanup:{en:'No cloud APIs, instances, firewall rules, or billable resources are used or created.',ta:'Cloud APIs, instances, firewall rules, கட்டண resources பயன்படுத்தவோ உருவாக்கவோ இல்லை.'}},
    questions:[
      {question:{en:'Which reply destination port matches the example client connection?',ta:'எடுத்துக்காட்டு client connection-ன் reply destination port எது?'},options:{en:['53000','Always 443','Always 8080'],ta:['53000','எப்போதும் 443','எப்போதும் 8080']},answer:0,explanation:{en:'The response reverses the original flow endpoints; a stateless rule must allow that direction.',ta:'Response அசல் flow endpoints-ஐத் திருப்புகிறது; stateless rule அந்தத் திசையை அனுமதிக்க வேண்டும்.'}},
      {question:{en:'What does an AWS security group provide here?',ta:'இங்கே AWS security group என்ன வழங்கும்?'},options:{en:['Stateful allow-rule filtering','A replacement for route tables','Guaranteed application health'],ta:['Stateful allow-rule filtering','Route tables-க்கு மாற்று','உறுதியான application health']},answer:0,explanation:{en:'State recognition and allow policy do not install routes or validate application dependencies.',ta:'State அறிதல், allow policy routes நிறுவவோ application dependencies validate செய்யவோாது.'}},
      {question:{en:'Local health curl works but balancer checks fail. What is a useful next check?',ta:'Local health curl வென்றும் balancer check தோற்றால் அடுத்து எதைப் பார்ப்பது?'},options:{en:['Bind address, health source, target port, and path','Only the client’s browser theme','Assume a private IP cannot be filtered'],ta:['Bind address, health source, target port, path','Client browser theme மட்டும்','Private IP-ஐ filter செய்ய முடியாது என நினைத்தல்']},answer:0,explanation:{en:'The remote health-check conversation differs from a loopback request on the target.',ta:'Remote health-check உரையாடல் target-ன் loopback request-இலிருந்து வேறுபடும்.'}}
    ],refs:[['AWS VPC route tables','https://docs.aws.amazon.com/vpc/latest/userguide/VPC_Route_Tables.html'],['AWS security groups and network ACLs','https://docs.aws.amazon.com/vpc/latest/userguide/infrastructure-security.html'],['AWS Application Load Balancer health checks','https://docs.aws.amazon.com/elasticloadbalancing/latest/application/target-group-health-checks.html']]
  },
  {
    id:46,module:10,model:'services',
    title:{en:'Kubernetes Services, CNI, and NetworkPolicy',ta:'Kubernetes Services, CNI, NetworkPolicy செயல்படும் விதம்'},
    summary:{en:'Trace traffic from a Service name to selected Pod endpoints and separate API declarations, networking implementation, and bidirectional policy enforcement.',ta:'Service பெயரிலிருந்து தேர்ந்த Pod endpoints வரை traffic பின்தொடர்ந்து API அறிவிப்பு, networking implementation, இருதிசை policy enforcement ஆகியவற்றைப் பிரித்தறிவோம்.'},
    prerequisites:{en:'Containers, network namespaces, IP routing, DNS, port translation, and label selectors.',ta:'Containers, network namespaces, IP routing, DNS, port translation, label selectors தெரிந்திருக்க வேண்டும்.'},
    objectives:{en:['Distinguish Pod IPs, ClusterIP, EndpointSlices, and service ports.','Explain CNI responsibility without assuming one universal data plane.','Evaluate additive ingress and egress policies including DNS dependencies.'],ta:['Pod IP, ClusterIP, EndpointSlices, service ports வேறுபடுத்துதல்.','ஒரே data plane என ஊகிக்காமல் CNI பொறுப்பை விளக்குதல்.','DNS சார்புடன் additive ingress, egress policies மதிப்பிடுதல்.']},
    sections:[
      {heading:{en:'A Service selects a changing endpoint set',ta:'Service மாறும் endpoint தொகுதியைத் தேர்கிறது'},body:{en:'Pods have network identities that can change as workloads are replaced. A normal ClusterIP Service offers a stable virtual destination and selects backend Pods through labels, with EndpointSlices representing discovered endpoints and readiness-related information. Service port and targetPort can differ. Headless Services have different DNS and addressing behavior and do not use the same virtual-IP abstraction. A DNS answer for a Service therefore does not prove that it has usable endpoints, that the application listens on targetPort, or that policy permits delivery.',ta:'Workloads மாற்றப்படும்போது Pods-ன் network identity மாறலாம். வழக்கமான ClusterIP Service நிலையான virtual destination தந்து labels மூலம் backend Pods தேர்கிறது; EndpointSlices கண்ட endpoints, readiness தகவல் காட்டும். Service port, targetPort வேறாகலாம். Headless Service-ன் DNS, addressing நடத்தை வேறு; அதே virtual-IP முறை அல்ல. எனவே Service DNS பதில் கிடைத்தாலே usable endpoints உண்டு, application targetPort-ல் கேட்கிறது, policy அனுமதிக்கிறது என்பதில்லை.'}},
      {heading:{en:'CNI is an integration boundary',ta:'CNI ஒரு ஒருங்கிணைப்பு எல்லை'},body:{en:'Container Network Interface plugins help configure container network attachment and related resources through a defined interface. The chosen networking implementation may route Pod prefixes, encapsulate traffic, program host filtering, or use an eBPF data plane. Service forwarding may be implemented by kube-proxy or an alternative; do not assume iptables is always the packet path. Underlay routing, encapsulation MTU, node firewalls, and IP address allocation can all fail independently of a healthy Kubernetes API server.',ta:'Container Network Interface plugins வரையறுக்கப்பட்ட interface மூலம் container network attachment, தொடர்புடைய resources அமைக்க உதவும். தேர்ந்த implementation Pod prefixes route செய்யலாம், traffic encapsulate செய்யலாம், host filtering அமைக்கலாம், eBPF data plane பயன்படுத்தலாம். Service forwarding kube-proxy அல்லது மாற்று முறையில் இருக்கலாம்; packet path எப்போதும் iptables அல்ல. Kubernetes API server நன்றாக இருந்தாலும் underlay routing, tunnel MTU, node firewall, IP allocation தனித்தனியாகத் தோற்கலாம்.'}},
      {heading:{en:'Policy selection and permission are different steps',ta:'Policy தேர்வும் அனுமதியும் வேறு படிகள்'},body:{en:'Standard NetworkPolicy requires an implementation that enforces it. A Pod becomes isolated for a direction when an applicable policy selects it for that direction; allowed traffic is the union of applicable allow rules, not ordered firewall-style subtraction. For a connection between isolated Pods, source egress and destination ingress must both allow it. Replies to allowed connections are handled by the policy model, while DNS access may need an explicit egress allowance. Selector composition, namespaces, named ports, and address rewriting require implementation-aware tests.',ta:'Standard NetworkPolicy-க்கு அதை அமல்படுத்தும் implementation வேண்டும். பொருந்தும் policy ஒரு திசைக்கு Pod-ஐத் தேர்ந்தால் அந்தத் திசையில் isolation வரும்; அனுமதி பொருந்தும் allow rules-ன் union, வரிசையான firewall subtraction அல்ல. Isolated Pods இணைப்பில் source egress, destination ingress இரண்டும் அனுமதிக்க வேண்டும். அனுமதித்த connection replies policy model-ல் கையாளப்படும்; DNS-க்கு வெளிப்படையான egress அனுமதி தேவைப்படலாம். Selector சேர்க்கை, namespaces, named ports, address rewriting ஆகியவை implementation-aware சோதனை தேவைப்படுத்தும்.'}}
    ],
    example:{en:'A Service called catalog exposes port 80 and forwards to targetPort 8080 on Pods labeled app=catalog. Its DNS name can resolve while its EndpointSlice contains no ready backend because the selector says app=catalogue by mistake. After correcting the selector in a reviewed change, an isolated client may still need egress to DNS and TCP 8080, while the catalog Pod needs ingress from that client. Opening client ingress alone cannot repair blocked client egress.',ta:'catalog Service port 80-ஐ வெளியிட்டு app=catalog Pods-ன் targetPort 8080-க்கு அனுப்புகிறது. Selector தவறாக app=catalogue என்றால் DNS resolve ஆனாலும் EndpointSlice-ல் ready backend இருக்காது. ஆய்வு செய்யப்பட்ட மாற்றத்தில் selector சரிசெய்தபின்பும் isolated client-க்கு DNS, TCP 8080 egress தேவைப்படலாம்; catalog Pod client ingress அனுமதிக்க வேண்டும். Client ingress மட்டும் திறந்தால் தடுக்கப்பட்ட client egress சரியாகாது.'},
    failure:{en:'All Pod-to-Pod tests pass, but the Service fails. Inspect endpoint selection, readiness, service port translation, and service data-plane programming before restarting the CNI. If a default-deny egress policy breaks only names, compare DNS resolution with direct known-address access; that difference points toward DNS policy rather than every application backend.',ta:'Pod-to-Pod சோதனைகள் வென்றும் Service தோற்கிறது. CNI restart செய்வதற்குமுன் endpoint தேர்வு, readiness, port translation, service data-plane programming பார்க்கவும். Default-deny egress பிறகு பெயர்கள் மட்டும் தோற்றால் DNS-ஐ தெரிந்த address நேரடி அணுகலுடன் ஒப்பிடவும்; இது எல்லா backend கோளாறையும் விட DNS policy-ஐச் சுட்டும்.'},
    lab:{commands:"python3 - <<'PY'\npods=[{'name':'catalog-a','labels':{'app':'catalog'},'ready':True,'port':8080},{'name':'other','labels':{'app':'other'},'ready':True,'port':8080}]\nfor selector in ({'app':'catalog'},{'app':'catalogue'}):\n    endpoints=[p['name'] for p in pods if p['ready'] and all(p['labels'].get(k)==v for k,v in selector.items())]\n    print(selector,endpoints)\nfor egress,ingress in [(True,True),(False,True),(True,False)]:\n    print('egress',egress,'ingress',ingress,'allowed',egress and ingress)\nPY",guidance:{en:'Run Python 3 locally; no cluster or kubectl context is needed. The model assumes both endpoint directions are isolated and abstracts away node traffic and implementation exceptions.',ta:'Cluster, kubectl context இன்றி Python 3 உள்ளூரில் இயக்கவும். இரு endpoint திசைகளும் isolated என model கருதி node traffic, implementation விதிவிலக்குகளை ஒதுக்குகிறது.'},expected:{en:'The correct selector returns catalog-a and the misspelled selector returns an empty list. Only the True/True policy pair permits the modeled connection.',ta:'சரியான selector catalog-a தரும்; தவறான spelling காலிப் பட்டியல் தரும். True/True policy ஜோடி மட்டுமே model connection அனுமதிக்கும்.'},cleanup:{en:'No Kubernetes objects, namespaces, Pods, Services, or policies are created or changed.',ta:'Kubernetes objects, namespaces, Pods, Services, policies உருவாக்கவோ மாற்றவோ இல்லை.'}},
    questions:[
      {question:{en:'Service DNS works but no ready endpoints exist. What should be checked?',ta:'Service DNS இயங்கியும் ready endpoints இல்லை. எதைப் பார்ப்பது?'},options:{en:['Selector labels and Pod readiness','Only the DNS root servers','Only the Service name length'],ta:['Selector labels, Pod readiness','DNS root servers மட்டும்','Service பெயர் நீளம் மட்டும்']},answer:0,explanation:{en:'A stable Service name can exist independently of a usable selected backend set.',ta:'பயன்படும் backend தொகுதி இல்லாமலேயே நிலையான Service பெயர் இருக்கலாம்.'}},
      {question:{en:'Both Pods are isolated; source egress denies and destination ingress allows. Is the modeled connection permitted?',ta:'இரு Pods isolated; source egress தடை, destination ingress அனுமதி. Model connection அனுமதியா?'},options:{en:['No, both required directions must allow','Yes, ingress overrides egress','Yes, policies are evaluated alphabetically'],ta:['இல்லை; தேவையான இரு திசைகளும் அனுமதிக்க வேண்டும்','ஆம்; ingress egress-ஐ மீறும்','ஆம்; policy அகரவரிசையில் செயல்படும்']},answer:0,explanation:{en:'Applicable source egress and destination ingress checks are independent requirements.',ta:'பொருந்தும் source egress, destination ingress சோதனைகள் தனித்தனி தேவைகள்.'}},
      {question:{en:'Does creating NetworkPolicy guarantee enforcement on any plugin?',ta:'NetworkPolicy உருவாக்கினாலே எல்லா plugin-லும் enforcement உறுதியா?'},options:{en:['No, the network implementation must support it','Yes, the API server filters packets','Only if the object name contains deny'],ta:['இல்லை; network implementation ஆதரிக்க வேண்டும்','ஆம்; API server packets filter செய்யும்','Object பெயரில் deny இருந்தால் மட்டும்']},answer:0,explanation:{en:'The API stores desired policy; a capable data-plane implementation enforces it.',ta:'API desired policy சேமிக்கும்; திறனுள்ள data-plane implementation அதை அமல்படுத்தும்.'}}
    ],refs:[['Kubernetes Services','https://kubernetes.io/docs/concepts/services-networking/service/'],['Kubernetes NetworkPolicy','https://kubernetes.io/docs/concepts/services-networking/network-policies/'],['CNI specification','https://www.cni.dev/docs/spec/']]
  },
  {
    id:47,module:10,model:'qos',
    title:{en:'Mobile, satellite, and constrained IoT paths',ta:'Mobile, satellite, குறைந்த வளமுள்ள IoT பாதைகள்'},
    summary:{en:'Compare mobility, propagation delay, radio scheduling, and device energy budgets, then choose measurements and retry policies that fit the actual path rather than its marketing label.',ta:'Mobility, propagation delay, radio scheduling, சாதன energy budget ஒப்பிட்டு marketing பெயருக்குப் பதிலாக உண்மைப் பாதைக்கு ஏற்ற அளவீடு, retry policy தேர்வுசெய்வோம்.'},
    prerequisites:{en:'RTT, bandwidth-delay product, NAT, TCP and UDP, MTU, and application retries.',ta:'RTT, bandwidth-delay product, NAT, TCP/UDP, MTU, application retries தெரிந்திருக்க வேண்டும்.'},
    objectives:{en:['Separate radio attachment and mobility from application continuity.','Estimate satellite propagation bounds without claiming fixed RTT.','Explain fragmentation, sleeping devices, and bounded IoT retries.'],ta:['Radio attachment, mobility-ஐ application continuity-லிருந்து பிரித்தறிதல்.','நிலையான RTT உறுதி கூறாமல் satellite propagation வரம்பு மதிப்பிடுதல்.','Fragmentation, sleeping devices, வரம்புள்ள IoT retries விளக்குதல்.']},
    sections:[
      {heading:{en:'Mobile attachment is not end-to-end stability',ta:'Mobile attachment end-to-end நிலைத்தன்மை அல்ல'},body:{en:'A mobile access network authenticates devices, schedules shared radio resources, and connects sessions through a packet core. In 5G architecture the user-plane function forwards user traffic while other functions manage sessions and mobility. Handover can change delay and loss behavior even when an IP session survives. Carrier NAT, firewall idle timers, and changing access networks can still disrupt application connections. Record radio conditions, movement, address changes, and transport events separately rather than assuming a signal-strength icon describes the full network path.',ta:'Mobile access network சாதனத்தை authenticate செய்து பகிரப்பட்ட radio resources schedule செய்து packet core வழியாக sessions இணைக்கிறது. 5G-ல் user-plane function user traffic forward செய்யும்; மற்ற functions sessions, mobility நிர்வகிக்கும். IP session தொடர்ந்தாலும் handover delay, loss மாற்றலாம். Carrier NAT, firewall idle timers, access network மாற்றம் application connections பாதிக்கலாம். Radio நிலை, இயக்கம், address மாற்றம், transport நிகழ்வுகள் தனியாகப் பதிவாக வேண்டும்; signal icon முழுப் பாதையைச் சொல்லாது.'}},
      {heading:{en:'Satellite delay follows geometry and system design',ta:'Satellite delay வடிவியல், system வடிவமைப்பைச் சாரும்'},body:{en:'Propagation cannot outrun the speed of light. A geostationary satellite sits roughly 35,786 km above the equator; even an ideal ground-satellite-ground path adds substantial distance before terrestrial routing, processing, and queueing. Lower orbits can shorten propagation but introduce moving coverage, handovers, gateway choices, and possibly inter-satellite paths. Throughput also depends on scheduling, spectrum, weather-sensitive link behavior, and shared capacity. Performance-enhancing proxies can change transport behavior and have implications for end-to-end semantics and encrypted protocols.',ta:'Propagation ஒளியின் வேகத்தை மீறாது. Geostationary satellite பூமத்தியரேகைக்கு மேல் சுமார் 35,786 km உயரத்தில் உள்ளது; சிறந்த ground-satellite-ground பாதையில்கூட terrestrial routing, processing, queueing-க்கு முன் பெரும் தூரம் சேரும். குறைந்த orbit propagation குறைக்கலாம்; ஆனால் நகரும் coverage, handover, gateway தேர்வு, inter-satellite paths வரலாம். Throughput scheduling, spectrum, வானிலைப் பாதிப்பு, பகிரப்பட்ட capacity சாரும். Performance-enhancing proxies transport நடத்தையை மாற்றி end-to-end semantics, encrypted protocols மீது விளைவு தரலாம்.'}},
      {heading:{en:'Constrained devices optimize more than bytes per second',ta:'குறைந்த வள சாதனங்கள் speed மட்டும் மேம்படுத்துவதில்லை'},body:{en:'IoT devices may have tiny memory, low-rate links, long sleep intervals, and finite battery energy. Adaptation layers such as 6LoWPAN compress IPv6 headers and fragment packets to fit small link frames. If one IP packet spans many fragments, losing one can waste the airtime and energy of the rest. CoAP offers compact application exchanges and defined reliability behavior over datagram transports, but application retries still need bounds and duplicate handling. TCP can also be appropriate in constrained networks when state, packet size, and wake schedules are deliberately engineered.',ta:'IoT சாதனங்களுக்கு சிறிய memory, low-rate links, நீண்ட sleep இடைவெளி, வரம்புள்ள battery இருக்கலாம். 6LoWPAN போன்ற adaptation layers IPv6 headers compress செய்து சிறிய link frames-க்கு packets fragment செய்கின்றன. ஒரு IP packet பல fragments ஆகும்போது ஒன்று தொலைந்தாலும் மற்றவற்றின் airtime, energy வீணாகலாம். CoAP datagram transport மீது compact exchanges, reliability நடத்தை தரும்; application retries வரம்பும் duplicate கையாளுதலும் வேண்டும். State, packet size, wake schedule திட்டமிட்டால் constrained network-ல் TCP-யும் பொருந்தலாம்.'}}
    ],
    example:{en:'For an idealized GEO relay directly above both conceptual ground legs, one-way ground-satellite-ground distance is 2×35786 km. Dividing by 299792 km/s gives about 239 ms one-way, or 477 ms round trip before other delays. This is a geometric illustration, not a prediction for every satellite service. Separately, if a datagram requires four independently delivered fragments and each succeeds with probability 0.9, whole-datagram success is 0.9⁴=0.6561 before any link retries.',ta:'இரண்டு கற்பனை ground legs-க்கும் நேர்மேல் GEO relay என எளிமைப்படுத்தினால் ஒருதிசை ground-satellite-ground தூரம் 2×35786 km. 299792 km/s-ஆல் வகுத்தால் சுமார் 239 ms ஒருதிசை, 477 ms round trip; மற்ற delays இதில் இல்லை. இது வடிவியல் விளக்கம்; எல்லா satellite service கணிப்பு அல்ல. தனியாக நான்கு independent fragments தலா 0.9 வெற்றி வாய்ப்பு என்றால் link retries-க்கு முன் முழு datagram வெற்றி 0.9⁴=0.6561.'},
    failure:{en:'A battery sensor wakes, retries aggressively while coverage is poor, and drains much faster than expected. The packet counter alone hides radio wake and retransmission energy. Measure wake duration, retry count, message size, and acknowledgement timing; use bounded backoff and application duplicate protection rather than an endless immediate retry loop.',ta:'Battery sensor விழித்து coverage மோசமாக இருக்கும்போது தீவிரமாக retry செய்து விரைவில் battery தீர்கிறது. Packet count மட்டும் radio wake, retransmission energy காட்டாது. Wake duration, retry count, message size, acknowledgement நேரம் அளந்து, முடிவில்லாத உடனடி retry-க்கு பதிலாக bounded backoff, application duplicate பாதுகாப்பு பயன்படுத்த வேண்டும்.'},
    lab:{commands:"python3 - <<'PY'\nheight_km=35786\nc_km_s=299792\nprint('idealized_GEO_RTT_ms',round(4*height_km/c_km_s*1000,1))\nprint('four_fragment_success',round(.9**4,4))\nprint('bounded_retry_delays_s',[min(60,2**n) for n in range(7)])\nPY",guidance:{en:'Python 3 performs local calculations without contacting a modem, satellite service, or sensor. Fragment independence is an explicit simplifying assumption; real losses can be correlated.',ta:'Python 3 modem, satellite service, sensor அணுகாமல் உள்ளூரில் கணக்கிடும். Fragment independence என்பது வெளிப்படையான எளிமைப்படுத்தல்; உண்மை loss ஒன்றோடொன்று தொடர்புடையதாக இருக்கலாம்.'},expected:{en:'The model gives about 477.5 ms, 0.6561 success probability, and delays 1, 2, 4, 8, 16, 32, 60 seconds. Jitter would be a separate retry-policy choice.',ta:'சுமார் 477.5 ms, 0.6561 வெற்றி வாய்ப்பு, 1, 2, 4, 8, 16, 32, 60 seconds இடைவெளி வரும். Jitter தனியான retry-policy தேர்வு.'},cleanup:{en:'No device, radio, SIM, routing, or power settings are touched.',ta:'Device, radio, SIM, routing, power settings எதுவும் தொடப்படாது.'}},
    questions:[
      {question:{en:'What is the four-fragment success probability under the example assumptions?',ta:'எடுத்துக்காட்டு ஊகங்களில் நான்கு-fragment வெற்றி வாய்ப்பு என்ன?'},options:{en:['0.6561','0.9','3.6'],ta:['0.6561','0.9','3.6']},answer:0,explanation:{en:'All four independent fragments must succeed, so multiply 0.9 by itself four times.',ta:'நான்கு independent fragments-மும் வெல்ல வேண்டும்; 0.9-ஐ நான்கு முறை பெருக்க வேண்டும்.'}},
      {question:{en:'Does a strong mobile signal prove stable end-to-end application latency?',ta:'வலுவான mobile signal நிலையான end-to-end application latency நிரூபிக்குமா?'},options:{en:['No, scheduling, core paths, queues, and handovers still matter','Yes, all remaining delay is zero','Only if the icon says 5G'],ta:['இல்லை; scheduling, core paths, queues, handovers முக்கியம்','ஆம்; மீதமுள்ள delay பூஜ்யம்','Icon 5G என்றால் மட்டும்']},answer:0,explanation:{en:'Received radio power describes only part of a path with many additional delay sources.',ta:'பல delay மூலங்கள் கொண்ட பாதையின் ஒரு பகுதியை மட்டுமே radio power விவரிக்கிறது.'}},
      {question:{en:'What is a better response to repeated sensor transmission failures?',ta:'Sensor transmission தொடர்ந்து தோற்றால் சிறந்த பதில் எது?'},options:{en:['Bounded backoff with duplicate-safe application handling','Retry forever without waiting','Disable all acknowledgements regardless of requirements'],ta:['வரம்புள்ள backoff, duplicate-safe application கையாளுதல்','காத்திருக்காமல் முடிவில்லாமல் retry','தேவை பார்க்காமல் எல்லா acknowledgements நிறுத்துதல்']},answer:0,explanation:{en:'Bounded retry limits energy and congestion costs while duplicate handling protects application effects.',ta:'Bounded retry energy, congestion செலவு குறைக்கும்; duplicate handling application விளைவைப் பாதுகாக்கும்.'}}
    ],refs:[['3GPP 5G architecture specification 23.501','https://www.3gpp.org/dynareport/23501.htm'],['TCP over satellite channels','https://www.rfc-editor.org/rfc/rfc2488.html'],['IPv6 over IEEE 802.15.4','https://www.rfc-editor.org/rfc/rfc4944.html'],['CoAP','https://www.rfc-editor.org/rfc/rfc7252.html'],['TCP in IoT','https://www.rfc-editor.org/rfc/rfc9006.html']]
  },
  {
    id:48,module:10,model:'services',
    title:{en:'Network automation, reconciliation, and observability',ta:'Network automation, reconciliation மற்றும் செயல்நிலையைக் கண்டறிதல்'},
    summary:{en:'Turn configuration intent into reviewable changes and connect counters, logs, traces, and active probes to a precise operational question rather than collecting unbounded telemetry.',ta:'Configuration intent-ஐ ஆய்வு செய்யக்கூடிய மாற்றங்களாக மாற்றி, counters, logs, traces, active probes ஆகியவற்றை அளவில்லாமல் சேகரிக்காமல் தெளிவான operational கேள்வியுடன் இணைப்போம்.'},
    prerequisites:{en:'Routes, interfaces, structured data, counters, timestamps, and systematic troubleshooting.',ta:'Routes, interfaces, structured data, counters, timestamps, முறையான troubleshooting தெரிந்திருக்க வேண்டும்.'},
    objectives:{en:['Separate desired, running, and operational state.','Design bounded changes with validation and rollback evidence.','Calculate counter rates and combine independent observations to test hypotheses.'],ta:['Desired, running, operational state வேறுபடுத்துதல்.','Validation, rollback சான்றுடன் வரம்புள்ள மாற்றம் வடிவமைத்தல்.','Counter rates கணக்கிட்டு தனித்த சான்றுகளால் சந்தேகங்களைச் சோதித்தல்.']},
    sections:[
      {heading:{en:'Structured intent needs reconciliation',ta:'Structured intent-க்கு reconciliation தேவை'},body:{en:'Automation begins with an inventory and an explicit desired state, including device identity, interface ownership, address scope, and policy constraints. YANG models describe structured management data; NETCONF and RESTCONF expose operations and data through defined protocols rather than arbitrary screen scraping. Capabilities and datastore support must be discovered. A running configuration is not identical to operational state: a configured interface can be down, and a configured route can be unresolved. Reconciliation compares intended outcomes with observed reality and reports divergence instead of blindly replaying commands.',ta:'Automation inventory, வெளிப்படையான desired state மூலம் தொடங்கும்; device identity, interface ownership, address scope, policy வரம்புகள் சேரும். YANG structured management data விவரிக்கும்; NETCONF, RESTCONF வரையறுக்கப்பட்ட protocols மூலம் data, operations வழங்கும். Capabilities, datastore ஆதரவு கண்டறிய வேண்டும். Running configuration operational state-க்கு சமமல்ல; configured interface down ஆகலாம், route unresolved ஆகலாம். Reconciliation கண்மூடித்தனமாக commands திரும்பச் செய்யாமல் திட்டமிட்ட முடிவையும் உண்மையையும் ஒப்பிட்டு வேறுபாடு தெரிவிக்கும்.'}},
      {heading:{en:'A safe change is observable and bounded',ta:'நல்ல மாற்றம் வரம்புடனும் சான்றுடனும் அமைய வேண்டும்'},body:{en:'Generate a candidate diff, validate syntax and semantic constraints, and check that the target identity matches the inventory before writing. Idempotent intent should avoid unnecessary repeated changes, but idempotency alone does not make an incorrect policy safe. Use staged rollout and relevant pre/post checks, with rollback or confirmed-commit mechanisms only when the platform supports them. Preserve an administrative recovery path and distinguish an API acknowledgement from verified forwarding. Concurrent operators and controllers require conflict detection so automation does not repeatedly overwrite legitimate changes.',ta:'எழுதும்முன் candidate diff உருவாக்கி syntax, semantic வரம்பு சரிபார்த்து target identity inventory-க்கு பொருந்துகிறதா பார்க்க வேண்டும். Idempotent intent தேவையற்ற மறுமாற்றம் தவிர்க்கும்; தவறான policy பாதுகாப்பாகிவிடாது. Platform ஆதரித்தால் மட்டுமே rollback அல்லது confirmed-commit கொண்டு staged rollout, pre/post checks பயன்படுத்தவும். நிர்வாக recovery பாதை காத்து API acknowledgement-ஐ உண்மையான forwarding சரிபார்ப்பிலிருந்து பிரிக்க வேண்டும். மற்ற operators, controllers-ன் சரியான மாற்றங்களை மீண்டும் அழிக்காமல் conflict detection தேவை.'}},
      {heading:{en:'Telemetry has units, scope, and blind spots',ta:'Telemetry-க்கு units, scope, மறைந்த பகுதிகள் உண்டு'},body:{en:'Counters summarize events, gauges describe current values, logs record discrete context, and traces connect application work across components. Compute a counter rate from deltas over a measured interval, accounting for resets, wraps, and changing interfaces. High-cardinality labels can overwhelm storage, and packet captures can reveal sensitive payloads, so choose collection scope deliberately. Correlate clocks and flow direction before joining observations. A successful synthetic probe tests its own path and operation, not every user. Define service objectives around meaningful latency, availability, and error populations.',ta:'Counters நிகழ்வுகளைச் சேர்த்துக் காட்டும்; gauges தற்போதைய மதிப்பு; logs தனி நிகழ்வின் சூழல்; traces பல components-ன் application வேலையை இணைக்கும். Counter reset, wrap, interface மாற்றம் கருத்தில் கொண்டு அளந்த இடைவெளியின் delta மூலம் rate கணக்கிடவும். அதிக cardinality labels storage சுமை தரலாம்; capture sensitive payload காட்டலாம்; சேகரிப்பு வரம்பைத் திட்டமிட வேண்டும். சான்றுகள் இணைக்கும்முன் clocks, flow திசை பொருத்தவும். Synthetic probe தன் பாதை, செயலை மட்டுமே சோதிக்கும்; எல்லா users அல்ல. பொருத்தமான latency, availability, error தொகுதியில் service objectives வரையறுக்க வேண்டும்.'}}
    ],
    example:{en:'An interface octet counter rises from 1,000,000 to 1,750,000 during a measured two-second interval. The rate is 375,000 bytes/s or 3 Mbit/s, not 750,000 bytes/s. A simultaneous application trace shows a 400 ms database wait while route and loss probes remain normal, suggesting an application dependency rather than link saturation. An automation plan to fix a missing route should show the intended route diff and verify next-hop resolution and a representative transaction after application.',ta:'Interface octet counter அளந்த இரண்டு seconds-ல் 1,000,000 முதல் 1,750,000 ஆக உயர்கிறது. Rate 375,000 bytes/s அல்லது 3 Mbit/s; 750,000 bytes/s அல்ல. அதே நேரம் application trace database wait 400 ms காட்டி route, loss probes இயல்பாக இருந்தால் link saturation-ஐவிட application dependency சந்தேகம். Missing route சரிசெய்யும் automation திட்டம் route diff காட்டி பின்னர் next-hop resolution, பிரதிநிதி transaction சரிபார்க்க வேண்டும்.'},
    failure:{en:'A device/agent counter resets, or the collector switches counter identity, and a counter drops from 900000 to 1000. Naively subtracting yields a negative traffic rate or a huge unsigned spike. Treat this as a suspected discontinuity until identity/reset context confirms its cause, and mark the interval unavailable instead of inventing throughput. Likewise, a deployment reporting success after an API write can conceal a failed next hop unless operational checks are part of completion.',ta:'Device/agent counter reset அல்லது collector counter identity மாற்றத்தால் counter 900000-லிருந்து 1000 ஆகக் குறைகிறது; collector restart மட்டும் remote counter reset செய்யாது. நேரடிக் கழித்தல் negative rate அல்லது மிகப் பெரிய unsigned spike தரும். Throughput கற்பனை செய்யாமல் reset கண்டறிந்து அந்த interval கிடைக்காததாகக் குறிக்க வேண்டும். அதேபோல் API write வெற்றி என்ற deployment அறிக்கை operational check இல்லாவிட்டால் failed next hop-ஐ மறைக்கலாம்.'},
    lab:{commands:"python3 - <<'PY'\nfor before,after,seconds in [(1_000_000,1_750_000,2),(900_000,1000,2)]:\n    if after<before:\n        print('reset_detected_interval_unavailable')\n    else:\n        bps=(after-before)*8/seconds\n        print('bytes_per_second',bps/8,'Mbit_per_second',bps/1e6)\ndesired={'prefix':'192.0.2.0/24','next_hop':'192.0.2.1'}\nobserved={'prefix':'192.0.2.0/24','next_hop':'192.0.2.2'}\nprint('candidate_diff',{k:(observed.get(k),v) for k,v in desired.items() if observed.get(k)!=v})\nPY",guidance:{en:'The Python 3 exercise calculates rates and a candidate dictionary diff without applying it. Its documentation addresses are inert data, not a valid route design for the host.',ta:'Python 3 rate, candidate dictionary diff கணக்கிடும்; அமல்படுத்தாது. Documentation addresses செயலற்ற data மட்டுமே; host-க்கான சரியான route வடிவமைப்பு அல்ல.'},expected:{en:'The first rate is 375000 bytes/s and 3 Mbit/s. The reset interval is unavailable, and the diff contains only the changed next_hop field.',ta:'முதல் rate 375000 bytes/s, 3 Mbit/s. Reset interval unavailable என வரும்; diff-ல் மாறிய next_hop field மட்டும் இருக்கும்.'},cleanup:{en:'No inventory files, device sessions, configuration writes, or telemetry collectors are created.',ta:'Inventory files, device sessions, configuration writes, telemetry collectors உருவாக்கப்படாது.'}},
    questions:[
      {question:{en:'What rate follows a 750000-byte increase over two seconds?',ta:'இரண்டு seconds-ல் 750000-byte உயர்வின் rate என்ன?'},options:{en:['3 Mbit/s','6 Mbit/s','750000 Mbit/s'],ta:['3 Mbit/s','6 Mbit/s','750000 Mbit/s']},answer:0,explanation:{en:'750000×8÷2 equals 3000000 bits per second.',ta:'750000 bytes-ஐ எட்டால் பெருக்கி இரண்டு seconds-ஆல் வகுத்தால் 3000000 bits per second கிடைக்கும்; இது 3 Mbit/s.'}},
      {question:{en:'What should the simple collector do when a counter decreases?',ta:'Counter குறைந்தால் இந்த எளிய collector என்ன செய்ய வேண்டும்?'},options:{en:['Mark a reset or discontinuity and avoid a fabricated rate','Always report negative bandwidth','Assume all links became faster'],ta:['Reset அல்லது discontinuity குறித்துக் கற்பனை rate தவிர்க்க','எப்போதும் negative bandwidth கூற','எல்லா links வேகமானதாக நினைக்க']},answer:0,explanation:{en:'Without reset/wrap context, the interval cannot be interpreted as ordinary monotonic traffic growth.',ta:'Reset/wrap சூழல் இல்லாமல் interval-ஐ வழக்கமான உயரும் traffic கணக்காகப் புரிந்துகொள்ள முடியாது.'}},
      {question:{en:'What evidence is stronger than a successful configuration API write?',ta:'வெற்றியான configuration API write-ஐவிட வலுவான சான்று எது?'},options:{en:['Verified operational state and the intended forwarding outcome','Only an HTTP 200 response','Repeatedly sending the same write'],ta:['Operational state, திட்டமிட்ட forwarding முடிவு சரிபார்ப்பு','HTTP 200 response மட்டும்','அதே write மீண்டும் அனுப்புதல்']},answer:0,explanation:{en:'Accepted intent and realized service behavior are distinct stages of automation.',ta:'ஏற்கப்பட்ட intent, உண்மையில் அமலான service நடத்தை automation-ன் தனித்த படிகள்.'}}
    ],refs:[['NETCONF','https://www.rfc-editor.org/rfc/rfc6241.html'],['YANG 1.1','https://www.rfc-editor.org/rfc/rfc7950.html'],['RESTCONF','https://www.rfc-editor.org/rfc/rfc8040.html'],['Network management datastore architecture','https://www.rfc-editor.org/rfc/rfc8342.html'],['Interface counters and discontinuities','https://www.rfc-editor.org/rfc/rfc2863.html']]
  },
];
